INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-twist-2-usa', 'N64', 'Chameleon Twist 2 (USA)', '1998', 'Action / Platformer', 'Sunsoft', '1', '3D Platformer', '3D platformer with verticality and improved mechanics.', 'Conquer the toy-like worlds and save the day.', 'The North American release of the acclaimed 3D sequel.', 'Chameleon Twist 2 (USA) is a visual treat. With its focus on vertical exploration and creative use of the tongue mechanic, it’s a hidden gem in the N64 library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chao-bandstand', 'N64', 'Chao Bandstand', '2022', 'Music / Sandbox', 'Independent', '1', 'ROM Hack', 'Exploration and social sim featuring the Sonic Chao.', 'Interact with Chao in a musical, festive environment.', 'A fan-made mod featuring the beloved Chao from Sonic.', 'Chao Bandstand is a cozy and musical experience. Visit the Chao and enjoy custom animations and themes in this charming N64 character-focused project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charlie-blasts-territory-europe', 'N64', 'Charlie Blast''s Territory (Europe)', '1998', 'Action / Platformer', 'Blitz Games', '1', '3D Platformer', 'Puzzle-platforming with explosives and logic.', 'Move bombs to the target area before they explode.', 'The European release of the strategic puzzle hit.', 'Charlie Blast''s Territory (Europe) requires careful planning and quick reflexes. Solve complex explosive puzzles in this unique 3D logic game for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charlie-blasts-territory-usa', 'N64', 'Charlie Blast''s Territory (USA)', '1998', 'Action / Platformer', 'Blitz Games', '1', '3D Platformer', 'Puzzle-platforming with explosives and logic.', 'Help Charlie clear the territory in the North American version.', 'The North American release of the explosive puzzler.', 'Charlie Blast''s Territory (USA) features dozens of challenging levels. Think steps ahead to clear the board without getting caught in the blast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charmy-the-bee-64-playable', 'N64', 'Charmy The Bee 64 Playable', '2021', 'Action / Platformer', 'Independent', '1', 'ROM Hack', '3D platforming featuring the Sonic series character.', 'Fly and dash through levels as the energetic bee.', 'A character-swap mod featuring Charmy the Bee.', 'Charmy The Bee 64 Playable brings the Team Chaotix member to the N64. Use his flight abilities to find stars and explore the castle in a brand new way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chester-the-otter', 'N64', 'Chester the Otter', '2020', 'Action / Platformer', 'Independent', '1', 'ROM Hack', '3D platforming featuring a custom otter protagonist.', 'Swim and slide through levels as Chester the Otter.', 'A charming character mod with custom aquatic physics.', 'Chester the Otter is a delightful fan project. Experience smooth swimming and sliding mechanics with a high-quality custom model in this unique N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chinese-mario-64-knockoff', 'N64', 'Chinese Mario 64 Knockoff', '2020', 'Action / Platformer', 'Independent', '1', 'ROM Hack', 'Surreal 3D platforming with low-quality, humorous assets.', 'Find the stars in a world that looks like a knockoff game.', 'A parody mod based on low-budget bootleg titles.', 'Chinese Mario 64 Knockoff is a hilarious and intentional mess. Explore bizarre levels and listen to distorted music in this funny N64 "bootleg" satire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chopper-attack-europe', 'N64', 'Chopper Attack (Europe)', '1997', 'Action / Shooter', 'LucasArts', '1', 'Helicopter Shooter', 'Helicopter-based combat with mission objectives.', 'Fly through dangerous territory and destroy enemy bases.', 'The European version of the high-octane aerial shooter.', 'Chopper Attack (Europe) features intense arcade-style helicopter combat. Choose your pilot and specialized chopper to take down a terrorist threat across diverse 3D landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chopper-attack-usa', 'N64', 'Chopper Attack (USA)', '1997', 'Action / Shooter', 'LucasArts', '1', 'Helicopter Shooter', 'Helicopter-based combat with mission objectives.', 'Master the aerial combat across 7 intense missions.', 'The North American release of the explosive helicopter sim.', 'Chopper Attack (USA) offers fast-paced dogfights and bombing runs. With multiple difficulty levels and a variety of weapons, it''s a solid action title for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choro-q-64-japan', 'N64', 'Choro Q 64 (Japan)', '1998', 'Racing', 'Takara', '2', 'Toy Racing', 'Arcade racing with customizable miniature cars.', 'Race through creative tracks and upgrade your tiny vehicle.', 'The first N64 entry in the beloved Japanese Penny Racers series.', 'Choro Q 64 (Japan) brings the charm of pull-back toy cars to the console. Customize your car with hundreds of parts and win the grand prix in this vibrant racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choro-q-64-ii---hacha-mecha-grand-prix-race-japan', 'N64', 'Choro Q 64 II - Hacha Mecha Grand Prix Race (Japan)', '1999', 'Racing', 'Takara', '2', 'Toy Racing', 'Arcade racing with improved physics and vehicle types.', 'Dominate the "Hacha Mecha" Grand Prix in this improved sequel.', 'The expanded Japanese sequel to the Choro Q racing hit.', 'Choro Q 64 II features even more bizarre parts and vehicle transformations. Race through cities, forests, and clouds in this content-packed N64 racing gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-kuukan-nighter-pro-yakyuu-king-japan', 'N64', 'Chou Kuukan Nighter Pro Yakyuu King (Japan)', '1997', 'Sports / Baseball', 'Namco', '2', 'Simulation', 'Professional baseball simulation with realistic stats.', 'Lead your team to the victory in the Pro Yakyuu league.', 'A polished Japan-exclusive baseball title.', 'Chou Kuukan Nighter Pro Yakyuu King offers a realistic take on Japanese baseball. Master the pitching and batting systems to become the king of the diamond.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-kuukan-nighter-pro-yakyuu-king-2-japan', 'N64', 'Chou Kuukan Nighter Pro Yakyuu King 2 (Japan)', '1998', 'Sports / Baseball', 'Namco', '2', 'Simulation', 'Professional baseball simulation with updated rosters.', 'Win the championship in the definitive sequel.', 'The second entry in the Pro Yakyuu King series for Japan.', 'Chou Kuukan Nighter Pro Yakyuu King 2 features improved animations and deeper management options, providing an authentic Japanese baseball experience on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-snobo-kids-japan', 'N64', 'Chou Snobo Kids (Japan)', '1997', 'Sports / Snowboarding', 'Racdym', '2', 'Arcade Sports', 'High-speed snowboarding with combat elements.', 'Win the races while using items to sabotage your rivals.', 'The Japanese version of the cult classic Snowboard Kids Plus.', 'Chou Snobo Kids (Japan) features extra characters and courses not found in the international version. Experience the ultimate 64-bit combat snowboarding title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('christmas-dream-64', 'N64', 'Christmas Dream 64', '2020', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming in a festive and magical winter world.', 'Recover the holiday spirits in this cozy custom world.', 'A charming Christmas-themed modification for Mario 64.', 'Christmas Dream 64 takes players to a winter wonderland. Enjoy festive decorations and custom snowy levels in this lighthearted and beautifully crafted N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('christmasplex-mall', 'N64', 'Christmasplex Mall', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming in a massive, holiday-themed shopping mall.', 'Explore the floors and find every hidden star in the mall.', 'A creative urban exploration mod with a Christmas twist.', 'Christmasplex Mall is a unique sandbox experience. Navigate through stores and food courts filled with holiday cheer and platforming secrets on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('city-tour-gp---zen-nihon-gt-senshuken-japan', 'N64', 'City-Tour GP - Zen-Nihon GT Senshuken (Japan)', '1996', 'Racing', 'Taito', '2', 'Arcade Racing', 'Professional GT racing with licensed Japanese cars.', 'Become the champion of the All-Japan GT Championship.', 'A realistic Japanese touring car racing simulation.', 'City-Tour GP features authentic tracks and licensed vehicles. Master the handling of high-performance GT cars in this technically impressive N64 racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter---sculptors-cut-usa', 'N64', 'Clay Fighter - Sculptor''s Cut (USA)', '1998', 'Fighting', 'Interplay', '4', '2.5D Fighting', '3D fighting game with clay-themed characters.', 'Defeat the final boss in this rare, expanded edition.', 'The extremely rare Blockbuster exclusive version of ClayFighter.', 'Clay Fighter - Sculptor''s Cut (USA) is one of the rarest N64 games. It includes extra characters and refined gameplay, making it the "Holy Grail" for N64 collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter-63-1-3-europe', 'N64', 'Clay Fighter 63 1-3 (Europe)', '1997', 'Fighting', 'Interplay', '4', '2.5D Fighting', '3D fighting game with quirky clay characters and humor.', 'Master the "Claymations" and defeat your wacky rivals.', 'The European release of the humorous clay-themed brawler.', 'Clay Fighter 63 1/3 (Europe) brings the puns and parodies to the N64. With its unique art style and over-the-top finishers, it''s a fighting game unlike any other.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter-63-1-3-usa', 'N64', 'Clay Fighter 63 1-3 (USA)', '1997', 'Fighting', 'Interplay', '4', '2.5D Fighting', '3D fighting game with quirky clay characters and humor.', 'Rise to the top of the clay-fighting circuit in America.', 'The North American release of the wacky fighting title.', 'Clay Fighter 63 1/3 (USA) is packed with parodies of famous fighting games. Battle as Bad Mr. Frosty or Earthworm Jim in this colorful and hilarious 64-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('command-&-conquer-europe-enfr', 'N64', 'Command & Conquer (Europe) (En,Fr)', '1999', 'Strategy / RTS', 'Westwood Studios', '2', 'Real-Time Strategy', 'Real-time strategy with base building and unit management.', 'Choose your faction and dominate the global conflict.', 'The N64 port of the legendary RTS with localized text.', 'Command & Conquer (Europe) brings the war between GDI and Nod to the console. Experience full 3D environments and strategic combat in this groundbreaking port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('command-&-conquer-germany', 'N64', 'Command & Conquer (Germany)', '1999', 'Strategy / RTS', 'Westwood Studios', '2', 'Real-Time Strategy', 'Real-time strategy with localized German text.', 'Command your armies to victory in this German edition.', 'The localized German version of the C&C strategy hit.', 'Command & Conquer (Germany) offers the full tactical experience for German fans. Manage resources and deploy units to conquer the map in this iconic N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('command-&-conquer-usa', 'N64', 'Command & Conquer (USA)', '1999', 'Strategy / RTS', 'Westwood Studios', '2', 'Real-Time Strategy', 'Real-time strategy with base building and unit management.', 'Destroy the enemy base and capture the global theater.', 'The North American release of the first 3D C&C experience.', 'Command & Conquer (USA) features a unique N64 engine that renders the classic RTS in full 3D. Control the battlefield and master the art of war on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day---debug-blue-plant', 'N64', 'Conker''s Bad Fur Day - Debug Blue Plant', '2000', 'Action / Adventure', 'Rare', '1', 'Debug Build', '3D platforming featuring debug tools and assets.', 'Explore the "Blue Plant" level with developer tools enabled.', 'A technical debug build of a specific Conker world.', 'Conker''s Bad Fur Day - Debug Blue Plant offers a fascinating look at the game''s assets. Manipulate the environment and study the code of this mature N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day---twelve-tales-plantz', 'N64', 'Conker''s Bad Fur Day - Twelve Tales Plantz', '1998', 'Action / Adventure', 'Rare', '1', 'Prototype', '3D platforming from the "Twelve Tales" era.', 'Explore the remains of the canceled, family-friendly Conker.', 'A mod restoring assets from the original "Twelve Tales" build.', 'Twelve Tales Plantz is a historical treasure. Experience the bright, "E-rated" aesthetic of Conker before it was transformed into the mature title we know today.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-europe', 'N64', 'Conker''s Bad Fur Day (Europe)', '2001', 'Action / Adventure', 'Rare', '1', '3D Platformer', 'Mature 3D platforming with cinematic parodies.', 'Survive a terrible hangover and find your way back to Berri.', 'The European release of the legendary mature adventure.', 'Conker''s Bad Fur Day (Europe) is a technical marvel. With full speech and adult humor, it pushed the boundaries of what was possible on a Nintendo 64 cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-usa', 'N64', 'Conker''s Bad Fur Day (USA)', '2001', 'Action / Adventure', 'Rare', '1', '3D Platformer', 'Mature 3D platforming with cinematic parodies.', 'Navigate a world of foul-mouthed characters and movie spoofs.', 'The definitive North American release of the mature hit.', 'Conker''s Bad Fur Day (USA) is a cult classic. From the Great Mighty Poo to the Matrix parodies, it''s a high-quality adventure that remains unique in the N64 library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-usa-beta-ects-2000-2000-08-26', 'N64', 'Conker''s Bad Fur Day (USA) (Beta) (ECTS 2000) (2000 08 26)', '2000', 'Action / Adventure', 'Rare', '1', 'Beta Build', '3D platforming in an unfinished, early developmental state.', 'Explore the game as it appeared at the ECTS 2000 show.', 'A rare beta build from mid-2000 showing early progress.', 'Conker''s Bad Fur Day (Beta) is a piece of gaming history. Discover early animations and level layouts that differ from the final retail release on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-usa-beta-ects-2000-2000-08-26-all-chapters-unlocked', 'N64', 'Conker''s Bad Fur Day (USA) (Beta) (ECTS 2000) (2000 08 26) (All Chapters Unlocked)', '2000', 'Action / Adventure', 'Rare', '1', 'Beta Build', '3D platforming with all levels accessible for testing.', 'Test any chapter from the ECTS 2000 build instantly.', 'An unlocked version of the ECTS 2000 beta for N64.', 'This specific beta build allows researchers and fans to jump to any point in the game''s development, revealing hidden assets and cutscenes in their early forms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-debug-build', 'N64', 'Conker''s Bad Fur Day Debug Build', '2000', 'Action / Adventure', 'Rare', '1', 'Debug Build', '3D platforming with developer menus and tools active.', 'Explore the game world with total control over variables.', 'A specialized build used by developers for testing.', 'Conker''s Bad Fur Day Debug Build lets you manipulate physics, spawn items, and teleport, offering a deep dive into the inner workings of Rare''s N64 swan song.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-ects-demo', 'N64', 'Conker''s Bad Fur Day ECTS Demo', '2000', 'Action / Adventure', 'Rare', '1', 'Demo', '3D platforming featuring the short trade-show demonstration.', 'Play the specific segment prepared for the ECTS trade show.', 'A focused demo build of Conker for the European trade show.', 'The ECTS Demo provides a snapshot of the game''s polish in late 2000. Experience a curated slice of the "Bad Fur Day" before it hit store shelves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-pal-prototype', 'N64', 'Conker''s Bad Fur Day PAL prototype', '2000', 'Action / Adventure', 'Rare', '1', 'Prototype', '3D platforming in a PAL-region early testing build.', 'Test the performance of the game in PAL format.', 'A rare prototype from the European development cycle.', 'Conker''s Bad Fur Day PAL prototype is essential for historians. It shows the adjustments made for European televisions during the final months of development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-bad-fur-day-uncensored', 'N64', 'Conker''s Bad Fur Day Uncensored', '2001', 'Action / Adventure', 'Rare', '1', 'Modified Version', 'Mature 3D platforming without the audio/visual bleeps.', 'Experience the dialogue as originally recorded by the team.', 'A fan-led project to remove censors from the final game.', 'Conker''s Bad Fur Day Uncensored restores the raw humor of the script. Hear every line exactly as intended by the developers in this definitive "adult" version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('costume-corrections-for-virtual-pro-wrestling-64', 'N64', 'Costume Corrections for Virtual Pro Wrestling 64', '1997', 'Wrestling', 'AKI Corporation', '4', 'Modification', 'Professional wrestling with corrected attire and assets.', 'Master the ring with visually accurate wrestler costumes.', 'A cosmetic fix mod for the Japanese wrestling classic.', 'Costume Corrections for VPW 64 restores authentic gear to the legends of wrestling. Enjoy the legendary AKI gameplay with a more realistic visual presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('counter-strike-164', 'N64', 'Counter Strike 1.64', '2021', 'Shooter', 'Independent', '1', 'Homebrew', 'Tactical first-person shooter in the N64 engine.', 'Defuse bombs or rescue hostages in low-poly arenas.', 'A creative port of Counter Strike mechanics to the N64.', 'Counter Strike 1.64 brings the classic PC shooter to the console. Experience tactical 64-bit combat on iconic maps like Dust II in this impressive fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cowboy-classic-sonic-y-64', 'N64', 'Cowboy Classic Sonic Y 64', '2022', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming featuring Sonic in a cowboy outfit.', 'Navigate the levels with Sonic''s speed and a western flair.', 'A character-focused mod for the Super Mario 64 engine.', 'Cowboy Classic Sonic Y 64 is a fun mashup. Explore the castle with Sonic''s custom model and Western-themed assets in this unique N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-exotica-usa', 'N64', 'Cruis''n Exotica (USA)', '1999', 'Racing', 'Eugene Jarvis Games', '4', 'Arcade Racing', 'High-speed arcade racing with diverse world locations.', 'Win races and unlock eccentric cars in this global tour.', 'The final N64 entry in the legendary Cruis''n trilogy.', 'Cruis''n Exotica (USA) features dinosaurs, underwater cities, and space tracks. It’s an over-the-top, high-octane racing experience that defines arcade fun on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-usa-europe', 'N64', 'Cruis''n USA (Europe)', '1996', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-speed arcade racing across American landmarks.', 'Win the cross-country race from LA to Washington D.C.', 'The European version of the classic Midway arcade port.', 'Cruis''n USA (Europe) brings the hit arcade racer to your living room. Drive through the Golden Gate Bridge and Mount Rushmore in this high-octane 64-bit racing debut.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-usa-usa', 'N64', 'Cruis''n USA (USA)', '1996', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-speed arcade racing across American landmarks.', 'Reach the top of the leaderboard and unlock secret cars.', 'The original North American release of the arcade hit.', 'Cruis''n USA (USA) is a piece of N64 history. Experience the raw speed and "cool" 90s aesthetic as you race across the United States in a variety of powerful vehicles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-usa-usa-rev-a', 'N64', 'Cruis''n USA (USA) (Rev A)', '1996', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-speed arcade racing with technical polish.', 'Complete the cross-country tour with improved stability.', 'An updated North American revision of Cruis''n USA.', 'Cruis''n USA (USA) (Rev A) provides minor bug fixes and performance tweaks, ensuring a smoother arcade racing experience on the Nintendo 64 hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-usa-usa-rev-b', 'N64', 'Cruis''n USA (USA) (Rev B)', '1996', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-speed arcade racing with final logic corrections.', 'Conquer the American roads in the most stable build.', 'The final technical revision of the original Cruis''n USA.', 'Cruis''n USA (USA) (Rev B) is the definitive version of the game, offering optimized performance and corrected assets for the ultimate retro racing session.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-world-europe', 'N64', 'Cruis''n World (Europe)', '1998', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-speed arcade racing across global locations.', 'Win the world tour and master tracks from Italy to Hawaii.', 'The European release of the ambitious Cruis''n sequel.', 'Cruis''n World (Europe) expands the scale with international tracks and better stunts. Master the wheelie and flip mechanics to beat your rivals across the globe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-world-usa', 'N64', 'Cruis''n World (USA)', '1998', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-speed arcade racing across global locations.', 'Unlock every secret vehicle, including the School Bus.', 'The North American release of the world-tour racer.', 'Cruis''n World (USA) is famous for its vibrant tracks and chaotic gameplay. It’s an arcade-perfect port that offers hours of high-speed fun for N64 fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crystal-caverns', 'N64', 'Crystal Caverns', '2020', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming in a shimmering underground environment.', 'Navigate the crystal-filled caves to find the hidden stars.', 'A visually stunning cave-themed mod for Mario 64.', 'Crystal Caverns features custom lighting and transparent textures. Explore the beautiful but dangerous underground world in this high-quality N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('curse-of-moonlight-v111', 'N64', 'Curse of Moonlight v1.1.1', '2022', 'Action / Adventure', 'Independent', '1', 'ROM Hack', '3D platforming with a dark, lunar-inspired atmosphere.', 'Break the moonlight curse by collecting the shadow stars.', 'A moody and difficult ROM hack for the SM64 engine.', 'Curse of Moonlight v1.1.1 offers a challenging adventure with a unique aesthetic. Navigate through "night-mode" levels in this atmospheric N64 community gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-robo-english', 'N64', 'Custom Robo (English)', '2021', 'Action / Adventure', 'Independent', '1', 'ROM Hack', 'Action-RPG and robot brawling with translated text.', 'Build the ultimate robot and win the Custom Robo Cup.', 'The fan-translated English version of the Japanese hit.', 'Custom Robo (English) finally allows Western players to enjoy the deep story and robot customization that made this series a legend in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-robo-japan', 'N64', 'Custom Robo (Japan)', '1999', 'Action / RPG', 'Noise', '2', 'Robot RPG', 'Action-RPG and robot brawling with deep customization.', 'Collect parts and battle rivals in futuristic 3D arenas.', 'The original Japanese release of the robot-battler.', 'Custom Robo (Japan) features fast-paced combat and hundreds of part combinations. Experience the origin of the franchise on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-robo-v2-japan', 'N64', 'Custom Robo V2 (Japan)', '2000', 'Action / RPG', 'Noise', '2', 'Robot RPG', 'Action-RPG and robot brawling with 2v2 combat support.', 'Conquer the new tournament and unlock the rarest parts.', 'The expanded Japanese sequel with improved mechanics.', 'Custom Robo V2 (Japan) adds a massive amount of content, including tag-team battles and more refined arenas. It is the peak of robot brawling on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cybertiger-europe', 'N64', 'CyberTiger (Europe)', '1998', 'Sports / Golf', 'EA Sports', '4', 'Arcade Sports', 'Arcade-style golf with a whimsical, cartoonish flair.', 'Outplay Tiger Woods in a variety of colorful courses.', 'The European version of the fun and accessible golf game.', 'CyberTiger (Europe) combines realistic golf physics with wacky power-ups. Play as a "cyber" version of Tiger Woods in this unique 3D sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cybertiger-usa', 'N64', 'CyberTiger (USA)', '1998', 'Sports / Golf', 'EA Sports', '4', 'Arcade Sports', 'Arcade-style golf with a whimsical, cartoonish flair.', 'Win the championship and unlock secret characters.', 'The North American release of the CyberTiger golf sim.', 'CyberTiger (USA) offers a faster, more arcade-like take on golf. With its unique character designs and diverse courses, it’s a refreshing sports game for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daffy-duck-starring-as-duck-dodgers-europe-enfrdeesitnl', 'N64', 'Daffy Duck Starring as Duck Dodgers (Europe) (En,Fr,De,Es,It,Nl)', '2000', 'Platformer', 'Sunsoft', '1', '3D Platformer', '3D action-platforming with a futuristic Looney Tunes theme.', 'Save the galaxy from the Martian threat as Duck Dodgers.', 'The European multi-language release of the Looney Tunes hit.', 'Daffy Duck Starring as Duck Dodgers (Europe) features great humor and creative level design. Navigate through space stations and alien worlds on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution---disney-dancing-museum-japan', 'N64', 'Dance Dance Revolution - Disney Dancing Museum (Japan)', '2000', 'Rhythm', 'Konami', '2', 'Music Game', 'Rhythm-based dancing with iconic Disney characters.', 'Follow the beat and dance along with Mickey and friends.', 'A Japan-exclusive Disney rhythm game for the N64.', 'Disney Dancing Museum is a vibrant and musical treat. Use the controller or a dance mat to hit the notes in this rare and charming Disney title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darius-the-janitor:-a-christmas-story', 'N64', 'Darius The Janitor: A Christmas Story', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming featuring a humble janitor protagonist.', 'Save Christmas from a holiday disaster in the castle.', 'A unique and humorous story-driven mod for Mario 64.', 'Darius The Janitor: A Christmas Story is a festive fan project. Play as Darius and solve puzzles to ensure the holiday season is a success in this N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-fan-film-sonic-64-world-hill', 'N64', 'Dark Fan Film Sonic 64 World Hill', '2022', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming in a dark, stylized "Hill" environment.', 'Explore a cinematic and moody world as Dark Sonic.', 'A fan-film inspired mod with a focus on atmosphere.', 'Dark Fan Film Sonic 64 World Hill features striking visuals and a dark tone. Experience the world of Sonic through a 64-bit cinematic lens.');
