INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-rift-europe', 'N64', 'Dark Rift (Europe)', '1997', 'Fighting', 'Natsume', '2', '3D Fighting', '3D weapon-based fighting game with a sci-fi theme.', 'Win the tournament across diverse intergalactic arenas.', 'The European release of the high-speed weapon fighter.', 'Dark Rift (Europe) features a diverse roster of alien warriors. Master the combos and special moves in this technically impressive 3D brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-rift-usa', 'N64', 'Dark Rift (USA)', '1997', 'Fighting', 'Natsume', '2', '3D Fighting', '3D weapon-based fighting game with a sci-fi theme.', 'Master the unique "Rift" mechanics to defeat your rivals.', 'The North American release of the futuristic 3D fighter.', 'Dark Rift (USA) is known for its fast frame rate and unique character designs. Experience intense 64-bit fighting action in a dark, sci-fi universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-shadow-64-rainbownite', 'N64', 'Dark Shadow 64 Rainbownite', '2020', 'Action', 'Independent', '1', 'ROM Hack', '3D platforming in a colorful, neon "night" environment.', 'Collect the rainbow stars in this vibrant custom world.', 'A visually striking and colorful Mario 64 modification.', 'Dark Shadow 64 Rainbownite features glowing textures and creative level design. Navigate through the neon darkness in this unique N64 fan adventure.');
