INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-sonic-over-super-64-eveil', 'N64', 'Dark Sonic over Super 64 EVEIL', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming with a dark, "evil" theme and high speed.', 'Navigate a more aggressive and darker version of Super 64.', 'An "Evil" themed character mod for the Super 64 project.', 'Dark Sonic over Super 64 EVEIL is designed for fans of the darker Sonic aesthetic. Experience faster gameplay and custom models in this intense N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deadly-arts-usa', 'N64', 'Deadly Arts (USA)', '1996', 'Fighting', 'Konami', '2', '3D Fighting', '3D arena fighting game with a realistic martial arts focus.', 'Win the underground tournament and master every style.', 'A technical 3D fighting game released in North America.', 'Deadly Arts (USA) features a robust character creator and diverse fighting styles. Compete in gritty arenas and prove your skill in this N64 brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('decor-galore-slide', 'N64', 'Decor Galore Slide', '2020', 'Platformer', 'Independent', '1', 'ROM Hack', 'High-speed sliding with a focus on interior design.', 'Reach the end of the decorated slide as fast as possible.', 'A creative mod set in a beautifully decorated indoor space.', 'Decor Galore Slide is a visual treat. Slide through rooms filled with detail and festive decorations in this short but sweet N64 platforming trial.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defi-au-tetris-magique-france', 'N64', 'Defi au Tetris Magique (France)', '1999', 'Puzzle', 'Nintendo', '2', 'Puzzle', 'Puzzle-matching with Disney characters and magic.', 'Solve Tetris-style puzzles with a magical Mickey twist.', 'The localized French version of Magical Tetris Challenge.', 'Defi au Tetris Magique (France) features the classic Capcom-Disney collaboration. Enjoy addictive puzzle gameplay with beautiful 64-bit animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densha-de-go!-64-japan', 'N64', 'Densha de Go! 64 (Japan)', '1999', 'Simulation', 'Taito', '1', 'Train Simulation', 'Realistic train simulation and time management.', 'Pilot various trains and arrive at the stations on time.', 'A specialized train simulator for the Japanese market.', 'Densha de Go! 64 (Japan) is a unique and relaxing experience. Manage your speed and braking to master the Japanese railways in this technical N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-64-japan', 'N64', 'Derby Stallion 64 (Japan)', '1998', 'Simulation', 'ASCII', '1', 'Horse Racing Simulation', 'Horse racing management and simulation.', 'Breed, train, and race your way to the top of the derby.', 'A deep and addictive horse racing sim from Japan.', 'Derby Stallion 64 (Japan) offers a complex look at the world of horse racing. Manage every aspect of your stable to produce a champion on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destruction-derby-64-europe-enfrde', 'N64', 'Destruction Derby 64 (Europe) (En,Fr,De)', '1999', 'Racing', 'Reflections', '4', 'Destruction Racing', 'Vehicular combat with high-speed racing and crashing.', 'Be the last car standing in the arena or win the race.', 'The European version of the destructive racing hit.', 'Destruction Derby 64 (Europe) features incredible damage physics for its time. Smash your way through rivals in intense bowl matches and race tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destruction-derby-64-usa', 'N64', 'Destruction Derby 64 (USA)', '1999', 'Racing', 'Reflections', '4', 'Destruction Racing', 'Vehicular combat with high-speed racing and crashing.', 'Master the art of the "total wreck" in this North American hit.', 'The definitive North American release of the car-combat title.', 'Destruction Derby 64 (USA) is a riot of twisted metal. With its variety of cars and satisfying destruction, it’s a must-play for fans of arcade mayhem on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('detective-luigi', 'N64', 'Detective Luigi', '2020', 'Action / Adventure', 'Independent', '1', 'ROM Hack', '3D exploration and mystery solving in the Mario 64 engine.', 'Find clues and solve the "case" of the haunted castle.', 'A creative mystery-themed mod featuring Luigi as a detective.', 'Detective Luigi puts a noir spin on the N64. Explore the castle grounds, talk to NPCs, and solve environmental puzzles in this unique and atmospheric fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dezaemon-3d-japan', 'N64', 'Dezaemon 3D (Japan)', '1998', 'Action / Creation', 'Athena', '1', 'Game Creation Tool', 'Shmup (Shoot ''em up) creation tool and shooter.', 'Design your own levels or play the pre-made 3D shooters.', 'A sophisticated shooter-maker tool exclusive to Japan.', 'Dezaemon 3D (Japan) allows players to create complex 3D shooters from scratch. It features a robust editor and an impressive soundtrack for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diddy-kong-racing-europe-enfrde', 'N64', 'Diddy Kong Racing (Europe) (En,Fr,De)', '1997', 'Racing', 'Rare', '4', 'Arcade Racing', 'Adventure-style racing with cars, planes, and hovercrafts.', 'Defeat Wizpig and save Timber''s Island in Europe.', 'The European release of the groundbreaking Rareware racer.', 'Diddy Kong Racing (Europe) features a full adventure mode and hidden secrets. Choose from diverse characters and master three vehicle types in this N64 classic.');
