INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diddy-kong-racing-japan', 'N64', 'Diddy Kong Racing (Japan)', '1997', 'Racing', 'Rare', '4', 'Arcade Racing', 'Adventure-style racing with localized Japanese text.', 'Beat the boss challenges and unlock Drumstick the rooster.', 'The Japanese release of the hit adventure-racing title.', 'Diddy Kong Racing (Japan) brings the high-speed fun of Timber''s Island to Japan. Experience the same deep campaign and addictive 4-player racing.');
