INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diddy-kong-racing-usa-enfr-rev-a', 'N64', 'Diddy Kong Racing (USA) (En,Fr) (Rev A)', '1997', 'Racing', 'Rare', '4', 'Arcade Racing', 'Adventure-style racing with final technical corrections.', 'Experience the ultimate racer with the most stable build.', 'The final North American revision of Diddy Kong Racing.', 'Diddy Kong Racing (USA) (Rev A) is the definitive version of the game, fixing minor glitches and optimizing the N64''s performance for high-speed racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinosaur-planet', 'N64', 'Dinosaur Planet', '2000', 'Action / Adventure', 'Rare', '1', 'Unreleased Prototype', 'Action-adventure with exploration and real-time combat.', 'Save the planet from the Scales army as Krystal or Sabre.', 'The legendary unreleased Rareware prototype for the N64.', 'Dinosaur Planet is a piece of gaming history. Experience the game that eventually became Star Fox Adventures in its original 64-bit form.');
