INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-64---banjo-kongzooie', 'N64', 'Donkey Kong 64 - Banjo-Kongzooie', '2021', 'Platformer', 'Rare / Community', '2', 'ROM Hack', '3D platforming crossover featuring Banjo-Kazooie assets.', 'Explore the DK Isles as the iconic bear and bird duo.', 'A creative mashup of the two biggest Rareware franchises.', 'Donkey Kong 64 - Banjo-Kongzooie allows you to play the massive DK adventure with Banjo''s moveset. A technical marvel for the N64 modding community.');
