INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-64---tag-anywhere', 'N64', 'Donkey Kong 64 - Tag Anywhere', '2020', 'Platformer', 'Rare / Community', '2', 'ROM Hack', '3D platforming with a quality-of-life gameplay overhaul.', 'Switch between Kongs instantly without using the tag barrel.', 'A must-play mod that fixes the biggest critique of DK64.', 'Donkey Kong 64 - Tag Anywhere revolutionizes the gameplay. Switch Kongs on the fly to solve puzzles faster and reduce backtracking in this N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-64-europe-enfrdees', 'N64', 'Donkey Kong 64 (Europe) (En,Fr,De,Es)', '1999', 'Platformer', 'Rare', '4', '3D Platformer', '3D platforming with massive worlds and 5 playable Kongs.', 'Stop King K. Rool''s Blast-o-Matic from destroying the island.', 'The European release of the record-breaking collect-a-thon.', 'Donkey Kong 64 (Europe) features thousands of collectibles and massive levels. Use the Expansion Pak to experience the largest adventure on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-64-japan', 'N64', 'Donkey Kong 64 (Japan)', '1999', 'Platformer', 'Rare', '4', '3D Platformer', '3D platforming with localized Japanese menus and text.', 'Recover the Golden Bananas and free your Kong friends.', 'The Japanese release of the massive Donkey Kong 64.', 'Donkey Kong 64 (Japan) brings the DK crew''s biggest mission to Japan. Experience the same humor, music, and deep gameplay that defined the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-64-usa', 'N64', 'Donkey Kong 64 (USA)', '1999', 'Platformer', 'Rare', '4', '3D Platformer', '3D platforming with a focus on exploration and minigames.', 'Collect every blueprint and crown to reach 101% completion.', 'The definitive North American release of the Rare classic.', 'Donkey Kong 64 (USA) is the ultimate collect-a-thon. With five unique characters and an incredible soundtrack, it''s a staple of the N64 library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-64-usa-demo', 'N64', 'Donkey Kong 64 (USA) (Demo)', '1999', 'Platformer', 'Rare', '4', 'Demo Build', '3D platforming featuring a curated slice of the game.', 'Experience the Jungle Japes level in this early preview.', 'A rare store-kiosk demo of the massive DK adventure.', 'Donkey Kong 64 (USA) (Demo) offers a glimpse into the game''s development. Play as DK in a limited environment designed to showcase the power of the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-64-kong-quest', 'N64', 'Donkey Kong 64 Kong Quest', '2020', 'Platformer', 'Rare / Community', '2', 'ROM Hack', '3D platforming with a "hard-mode" custom campaign.', 'Navigate through more difficult versions of the DK worlds.', 'A challenging ROM hack designed for DK64 veterans.', 'Donkey Kong 64 Kong Quest features revised level logic and tougher enemy placement. Test your skills in this intense fan-made N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-racing', 'N64', 'Donkey Kong Racing', '2001', 'Racing', 'Rare', '4', 'Cancelled Prototype', '3D platforming featuring an early look at the DK series.', 'Explore early concepts of what became the 3D DK game.', 'A technical restoration of early Donkey Kong N64 assets.', 'Donkey Kong Racing provides a "what could have been" look at the franchise''s evolution on the console, featuring custom models and early environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-64-europe', 'N64', 'Doom 64 (Europe)', '1997', 'Shooter', 'id Software', '4', 'First-Person Shooter', 'First-person shooter with a dark, atmospheric horror theme.', 'Stop the demonic invasion on a new moon of Phobos.', 'The European release of the technically superior N64 Doom.', 'Doom 64 (Europe) features entirely new assets and a creepy, ambient soundtrack. Experience the darkest entry in the series with smooth N64 performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-64-japan', 'N64', 'Doom 64 (Japan)', '1997', 'Shooter', 'id Software', '4', 'First-Person Shooter', 'First-person shooter with localized Japanese text.', 'Fight through 32 levels of hellish nightmare in Japan.', 'The Japanese version of the atmospheric Doom shooter.', 'Doom 64 (Japan) brings the redesigned demons and lighting effects to Japanese fans. Master the Unmaker and save humanity from the Mother Demon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-64-usa', 'N64', 'Doom 64 (USA)', '1997', 'Shooter', 'id Software', '4', 'First-Person Shooter', 'First-person shooter with custom lighting and new demons.', 'Use the Unmaker to seal the portals to the underworld.', 'The definitive North American release of the N64 exclusive.', 'Doom 64 (USA) is often considered the "true" Doom 3. With its haunting atmosphere and polished gameplay, it’s a premier FPS experience on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-64-usa-rev-a', 'N64', 'Doom 64 (USA) (Rev A)', '1997', 'Shooter', 'id Software', '4', 'First-Person Shooter', 'First-person shooter with technical polish and fixes.', 'Conquer the nightmare with the most stable US build.', 'An updated revision of the North American Doom 64.', 'Doom 64 (USA) (Rev A) provides minor technical improvements, ensuring the lighting and sound effects work perfectly on original N64 hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---nobita-to-3tsu-no-seireiseki-japan', 'N64', 'Doraemon - Nobita to 3tsu no Seireiseki (Japan)', '1997', 'Adventure', 'Epoch', '1', 'Story Adventure', 'Action-adventure with 3D platforming and gadgets.', 'Find the three elemental stones to save the world.', 'The first N64 entry in the popular Japanese anime series.', 'Doraemon - Nobita to 3tsu no Seireiseki features fun 3D platforming and iconic gadgets from the show. A charming Japan-exclusive title for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-2---nobita-to-hikari-no-shinden-japan', 'N64', 'Doraemon 2 - Nobita to Hikari no Shinden (Japan)', '1998', 'Adventure', 'Epoch', '1', 'Story Adventure', 'Action-adventure with improved graphics and minigames.', 'Explore the Temple of Light and defeat the ancient evil.', 'The second Doraemon adventure for the Nintendo 64.', 'Doraemon 2 features larger worlds and more interactive environments. Join Nobita and his friends in this polished and colorful Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-3---nobita-no-machi-sos!-japan', 'N64', 'Doraemon 3 - Nobita no Machi SOS! (Japan)', '2000', 'Adventure', 'Epoch', '1', 'Story Adventure', 'Action-adventure with a sci-fi city rescue theme.', 'Save the city from a global SOS threat using gadgets.', 'The third and final Doraemon title for the N64.', 'Doraemon 3 - Nobita no Machi SOS! offers the most refined gameplay of the series. Navigate a high-tech city and solve puzzles in this rare Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doubutsu-no-mori-japan', 'N64', 'Doubutsu no Mori (Japan)', '2001', 'Life Simulation', 'Nintendo', '4', 'Social Simulation', 'Social simulation and life management in real-time.', 'Live a peaceful life in a village full of animal neighbors.', 'The original Japanese release of the first Animal Crossing.', 'Doubutsu no Mori (Japan) is a landmark title. Experience the beginning of the social sim phenomenon with its unique real-time clock on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-smol-over-mario', 'N64', 'Dr. Smol over Mario', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming featuring a custom doctor character model.', 'Explore the Mushroom Kingdom as the mysterious Dr. Smol.', 'A character-swap mod for Super Mario 64.', 'Dr. Smol over Mario brings a unique custom model to the classic game. Experience the platforming with a fresh, community-designed look on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-sword-64-usa', 'N64', 'Dragon Sword 64 (USA)', '1999', 'Action', 'Electronic Arts', '2', 'Action Adventure', 'Action-adventure with a dark, cinematic narrative.', 'Defeat the ancient dragon threat to restore peace to the land.', 'An unreleased N64 project with impressive 3D visuals.', 'Dragon Sword 64 (USA) showcases what the N64 could do in its later years. Experience a gritty fantasy world with tactical combat in this fascinating "lost" title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drawn-to-life-64', 'N64', 'Drawn To Life 64', '2022', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming with a focus on creativity and drawing.', 'Restore the world by bringing your drawings to life.', 'A creative mod inspired by the DS title "Drawn to Life."', 'Drawn To Life 64 allows players to interact with a world that reacts to their creativity. Solve puzzles in this imaginative and unique N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-64-v11', 'N64', 'Dream 64 (V1.1)', '2021', 'Adventure', 'Independent', '1', 'Demo Project', 'Surreal 3D platforming with high-energy visuals.', 'Navigate through a dream-like world to collect the stars.', 'A vibrant and atmospheric ROM hack for Mario 64.', 'Dream 64 (V1.1) features custom textures and a serene soundtrack. Explore the floating islands of the subconscious in this beautifully designed N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-heroes-europe', 'N64', 'Dual Heroes (Europe)', '1997', 'Fighting', 'Hudson Soft', '2', '3D Fighting', '3D fighting game with superhero-style armor.', 'Defeat the Gyless Empire and become the ultimate hero.', 'The European release of the colorful sci-fi 3D brawler.', 'Dual Heroes (Europe) features a unique "Virtual-Arena" aesthetic. Choose from a roster of armored warriors and master their special moves in this stylized N64 fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-heroes-japan', 'N64', 'Dual Heroes (Japan)', '1997', 'Fighting', 'Hudson Soft', '2', '3D Fighting', '3D fighting game with superhero-style armor.', 'Save the world through martial arts and high-tech gear.', 'The original Japanese release of the sci-fi fighter.', 'Dual Heroes (Japan) brings anime-inspired action to the N64. Experience the fast-paced combat and unique character designs that define this intergalactic tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-heroes-usa', 'N64', 'Dual Heroes (USA)', '1997', 'Fighting', 'Hudson Soft', '2', '3D Fighting', '3D fighting game with superhero-style armor.', 'Rise through the ranks of the elite hero circuit.', 'The North American release of the armored fighting title.', 'Dual Heroes (USA) is a visual treat for fans of tokusatsu and superheroes. Engage in 360-degree combat across diverse alien landscapes on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duck-dodgers-starring-daffy-duck-usa-enfres', 'N64', 'Duck Dodgers Starring Daffy Duck (USA) (En,Fr,Es)', '2000', 'Platformer', 'Ubi Soft', '1', '3D Platformer', '3D action-platforming with sci-fi humor.', 'Reclaim the planet X from Marvin the Martian.', 'The North American release featuring multi-language support.', 'Duck Dodgers Starring Daffy Duck (USA) captures the wit of the cartoons. Navigate complex platforming sections and use futuristic gadgets in this high-quality Looney Tunes adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem---zero-hour-europe', 'N64', 'Duke Nukem - Zero Hour (Europe)', '1999', 'Shooter', 'Eurocom', '4', 'First-Person Shooter', 'Third-person shooter with time-travel missions.', 'Stop the alien invasion across different historical eras.', 'The European release of the N64-exclusive Duke Nukem adventure.', 'Duke Nukem - Zero Hour (Europe) features huge levels and a massive arsenal. Travel from the Old West to a post-apocalyptic future in this gritty and humorous N64 shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem---zero-hour-france', 'N64', 'Duke Nukem - Zero Hour (France)', '1999', 'Shooter', 'Eurocom', '4', 'First-Person Shooter', 'Third-person shooter with localized French text.', 'Eliminate the alien threat in this localized French edition.', 'The French version of the time-traveling Duke adventure.', 'Duke Nukem - Zero Hour (France) brings Duke''s signature attitude to French players. Master the third-person combat and save humanity across time on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem---zero-hour-usa', 'N64', 'Duke Nukem - Zero Hour (USA)', '1999', 'Shooter', 'Eurocom', '4', 'First-Person Shooter', 'Third-person shooter with time-travel missions.', 'Save the world''s babes and stop the alien''s evil plan.', 'The definitive North American release of Zero Hour.', 'Duke Nukem - Zero Hour (USA) is an N64 powerhouse. With 4-player multiplayer and a deep campaign, it’s one of the most content-rich shooters on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem-64-europe', 'N64', 'Duke Nukem 64 (Europe)', '1997', 'Shooter', '3D Realms', '4', 'First-Person Shooter', 'First-person shooter with 3D environments and 2D sprites.', 'Blast through LA and stop the alien invasion.', 'The European version of the legendary PC port.', 'Duke Nukem 64 (Europe) features redesigned 3D weapons and localized content. Experience the ultimate "macho" shooter with split-screen multiplayer on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem-64-france', 'N64', 'Duke Nukem 64 (France)', '1997', 'Shooter', '3D Realms', '4', 'First-Person Shooter', 'First-person shooter with localized French assets.', 'Clear the streets of Paris and LA in this French edition.', 'The localized French version of Duke Nukem 64.', 'Duke Nukem 64 (France) offers the classic high-octane FPS action for the French market. Use the Shrink Ray and RPG to decimate your alien foes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem-64-usa', 'N64', 'Duke Nukem 64 (USA)', '1997', 'Shooter', '3D Realms', '4', 'First-Person Shooter', 'First-person shooter with 3D environments and 2D sprites.', 'Hail to the king, baby! Save Earth from the alien horde.', 'The iconic North American release of the FPS classic.', 'Duke Nukem 64 (USA) is the definitive way to play Duke on the N64. Featuring refined levels and the Expansion Pak support, it''s an essential piece of any shooter collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-3d-europe-enfrdeesit', 'N64', 'Earthworm Jim 3D (Europe) (En,Fr,De,Es,It)', '1999', 'Platformer', 'Shiny Entertainment', '1', '3D Platformer', '3D platforming with a focus on surreal humor.', 'Navigate Jim''s subconscious to recover his marbles.', 'The European multi-language release of the 3D sequel.', 'Earthworm Jim 3D (Europe) brings the wacky world of Jim to the third dimension. Battle weird bosses and solve environmental puzzles in this colorful N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-3d-usa', 'N64', 'Earthworm Jim 3D (USA)', '1999', 'Platformer', 'Shiny Entertainment', '1', '3D Platformer', '3D platforming with a focus on surreal humor.', 'Help Jim escape his coma and defeat Psy-Crow.', 'The North American release of the lizard-suit hero''s 3D debut.', 'Earthworm Jim 3D (USA) is packed with the series'' signature wit and bizarre level design. Explore Jim''s brain and collect the golden udders in this unique 64-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecw-hardcore-revolution-europe', 'N64', 'ECW Hardcore Revolution (Europe)', '2000', 'Wrestling', 'Acclaim', '4', 'Sports Wrestling', 'Professional wrestling with a focus on hardcore rules.', 'Win the ECW World Heavyweight Championship.', 'The European release of the gritty hardcore wrestling game.', 'ECW Hardcore Revolution (Europe) features the high-impact style of the famous promotion. Master the weapons and brutal moves in this intense N64 wrestling title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecw-hardcore-revolution-usa', 'N64', 'ECW Hardcore Revolution (USA)', '2000', 'Wrestling', 'Acclaim', '4', 'Sports Wrestling', 'Professional wrestling with a focus on hardcore rules.', 'Defeat the legends of ECW in bloody, weapon-filled matches.', 'The North American release of the hardcore wrestling hit.', 'ECW Hardcore Revolution (USA) uses the acclaimed Acclaim engine to deliver a visceral wrestling experience. Step into the extreme ring on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('egg-slide', 'N64', 'Egg Slide', '2020', 'Platformer', 'Independent', '1', 'ROM Hack', 'High-speed sliding featuring an egg-based physics object.', 'Reach the bottom of the track without breaking the egg.', 'A creative physics-based sliding mod for Mario 64.', 'Egg Slide is a test of balance and speed. Navigate through steep drops and sharp turns while protecting your fragile cargo in this unique N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eikou-no-saint-andrews-japan', 'N64', 'Eikou no Saint Andrews (Japan)', '1996', 'Sports', 'Nintendo', '4', 'Golf Simulation', 'Realistic golf simulation set in the historic St. Andrews.', 'Master the oldest golf course in the world.', 'A technical, Japan-exclusive golf title.', 'Eikou no Saint Andrews features realistic wind and terrain physics. Experience the prestigious atmosphere of Scottish golf on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elmos-letter-adventure-usa', 'N64', 'Elmo''s Letter Adventure (USA)', '1999', 'Educational', 'Realtime Associates', '1', 'Educational Adventure', 'Educational 3D exploration with a focus on literacy.', 'Help Elmo find the missing letters in the Mushroom Kingdom.', 'A family-friendly educational title for young learners.', 'Elmo''s Letter Adventure (USA) uses 3D environments to teach basic spelling and reading skills. A charming and accessible title for the youngest N64 fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elmos-number-journey-usa', 'N64', 'Elmo''s Number Journey (USA)', '1999', 'Educational', 'Realtime Associates', '1', 'Educational Adventure', 'Educational 3D exploration with a focus on numeracy.', 'Help Elmo count and solve basic math puzzles.', 'A family-friendly educational title focused on numbers.', 'Elmo''s Number Journey (USA) makes learning math fun through exploration and interactive games. It''s the perfect introductory 3D experience for kids on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eltale-monsters-japan', 'N64', 'Eltale Monsters (Japan)', '1997', 'RPG', 'Visit', '1', 'Turn-Based RPG', 'Turn-based RPG with creature collection and evolution.', 'Capture and train monsters to save the fantasy world.', 'The Japanese version of the RPG "Quest 64."', 'Eltale Monsters (Japan) offers a unique spell-casting system and vibrant 3D world. Experience the original vision of this N64 role-playing adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emote-challenge-64', 'N64', 'Emote Challenge 64', '2022', 'Party', 'Independent', '4', 'Mini-Game Collection', 'Social interaction and minigame challenge.', 'Express the correct "emotes" to win the social game.', 'A unique mod focused on character animations and social play.', 'Emote Challenge 64 is a creative fan project that tests your reflexes and social timing. Use custom animations to beat the high score in this N64 community mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emotiguy', 'N64', 'Emotiguy', '2021', 'Party', 'Independent', '2', 'Experimental', '3D platforming featuring a custom "Emotiguy" character.', 'Navigate the castle as the expressive internet mascot.', 'A character-swap mod for the Super Mario 64 engine.', 'Emotiguy brings a unique visual style to the N64. Play as the custom-modeled emoji character and experience the classic levels with a fresh look.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eric-cartman-v10', 'N64', 'Eric Cartman v1.0', '2020', 'Platformer', 'Independent', '1', 'Character Mod', '3D platforming featuring the iconic South Park character.', 'Cause chaos in the Mushroom Kingdom as Eric Cartman.', 'A hilarious character mod for Super Mario 64.', 'Eric Cartman v1.0 features a custom 3D model of the South Park star. Explore the castle and defeat Bowser with Cartman''s signature attitude on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('escape-from-the-jail-definitive-edition', 'N64', 'Escape from the Jail Definitive Edition', '2023', 'Action', 'Independent', '1', 'ROM Hack', 'Stealth and escape-based 3D platforming.', 'Break out of the high-security jail and reach freedom.', 'A polished and expanded version of the prison-escape mod.', 'Escape from the Jail Definitive Edition features complex puzzles and guard patrols. Use your wits and agility to bypass the security in this intense N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evil-mortys-master-plan', 'N64', 'Evil Morty''s Master Plan', '2023', 'Action', 'Independent', '1', 'ROM Hack', '3D platforming with a dark, narrative-driven crossover theme.', 'Foil the plans of Evil Morty in this Rick & Morty mod.', 'A creative crossover mod featuring custom models and story.', 'Evil Morty''s Master Plan brings the multiverse to the N64. Explore high-tech environments and navigate the dangerous scheme of the smartest Morty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evo-q', 'N64', 'Evo Q', '1997', 'Racing', 'SETA', '2', 'Futuristic Racing', 'Futuristic racing with evolving vehicle mechanics.', 'Upgrade and evolve your craft during the high-speed races.', 'A technical racing mod focused on vehicle progression.', 'Evo Q features a unique "evolution" system where your car changes as you win. Master the high-speed tracks and adapt to your craft''s growth on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('excitebike-64-europe', 'N64', 'Excitebike 64 (Europe)', '2000', 'Racing', 'Nintendo', '4', 'Motorbike Racing', 'Realistic motocross racing with physics and stunts.', 'Win the championship and master the hill-climb mode.', 'The European release of the premier N64 dirt-bike racer.', 'Excitebike 64 (Europe) features incredible bike physics and diverse tracks. From indoor arenas to outdoor mud tracks, it’s a masterclass in 64-bit racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('excitebike-64-japan', 'N64', 'Excitebike 64 (Japan)', '2000', 'Racing', 'Nintendo', '4', 'Motorbike Racing', 'Realistic motocross racing with physics and stunts.', 'Defeat your rivals in the official Japanese competition.', 'The Japanese release of the acclaimed motocross title.', 'Excitebike 64 (Japan) brings the classic NES franchise into full 3D. Experience the same deep physics and addictive gameplay that defined the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('excitebike-64-usa', 'N64', 'Excitebike 64 (USA)', '2000', 'Racing', 'Nintendo', '4', 'Motorbike Racing', 'Realistic motocross racing with physics and stunts.', 'Master the "Excite 3D" mode and unlock the NES original.', 'The definitive North American release of the racing classic.', 'Excitebike 64 (USA) is widely considered one of the best racers on the system. With its steep learning curve and rewarding stunts, it''s a must-play for N64 fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('excitebike-64-usa-rev-a', 'N64', 'Excitebike 64 (USA) (Rev A)', '2000', 'Racing', 'Nintendo', '4', 'Motorbike Racing', 'Realistic motocross racing with bug fixes and polish.', 'Experience the ultimate dirt-bike race with the stable build.', 'An updated North American revision of Excitebike 64.', 'Excitebike 64 (USA) (Rev A) provides minor technical improvements, ensuring the bike collisions and terrain rendering are optimized for original hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-shell-delivery', 'N64', 'Extreme Shell Delivery', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming focused on high-speed projectile delivery.', 'Launch the Koopa shell through targets and narrow gaps.', 'A technical skill-based mod for the Mario 64 engine.', 'Extreme Shell Delivery is a test of precision and momentum. Use the Koopa shell to complete delivery missions in custom environments on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-g-europe-enfrdeesit', 'N64', 'Extreme-G (Europe) (En,Fr,De,Es,It)', '1997', 'Racing', 'Probe Entertainment', '4', 'Futuristic Racing', 'High-speed futuristic motorcycle racing with weapons.', 'Win the championship and destroy rivals with high-tech arsenal.', 'The European multi-language release of the sci-fi racer.', 'Extreme-G (Europe) features gravity-defying tracks and sonic booms. Battle across futuristic landscapes with unique weapons and bikes in this fast-paced N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-g-japan', 'N64', 'Extreme-G (Japan)', '1997', 'Racing', 'Probe Entertainment', '4', 'Futuristic Racing', 'High-speed futuristic motorcycle racing with weapons.', 'Dominate the futuristic circuits in this Japanese edition.', 'The Japanese release of the high-octane motorcycle racer.', 'Extreme-G (Japan) brings the intense speed and combat of the G-Force to Japan. Master the loop-de-loops and corkscrews in this visually stunning 64-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-g-usa', 'N64', 'Extreme-G (USA)', '1997', 'Racing', 'Probe Entertainment', '4', 'Futuristic Racing', 'High-speed futuristic motorcycle racing with weapons.', 'Reach Mach 1 and eliminate the competition to win.', 'The North American release of the iconic futuristic racer.', 'Extreme-G (USA) is an adrenaline-fueled experience. With its deep weapon system and incredible sense of speed, it remains a standout title in the N64 racing library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-g-xg2-europe-enfrdeesit', 'N64', 'Extreme-G XG2 (Europe) (En,Fr,De,Es,It)', '1998', 'Racing', 'Probe Entertainment', '4', 'Futuristic Racing', 'High-speed futuristic racing with evolved bikes and tracks.', 'Win the XG2 tournament using enhanced speed and fire-power.', 'The European sequel to the hit futuristic racer.', 'Extreme-G XG2 (Europe) takes the speed even further. Featuring more complex tracks and improved bike physics, it''s a high-stakes battle for the finish line on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-g-xg2-japan', 'N64', 'Extreme-G XG2 (Japan)', '1998', 'Racing', 'Probe Entertainment', '4', 'Futuristic Racing', 'High-speed futuristic racing with evolved bikes and tracks.', 'Conquer the global rankings in the Japanese sequel.', 'The Japanese version of the expanded XG2 sequel.', 'Extreme-G XG2 (Japan) offers more bikes, more weapons, and faster gameplay. Experience the pinnacle of futuristic combat racing with localized Japanese text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-g-xg2-usa', 'N64', 'Extreme-G XG2 (USA)', '1998', 'Racing', 'Probe Entertainment', '4', 'Futuristic Racing', 'High-speed futuristic racing with evolved bikes and tracks.', 'Break the sound barrier and outlast your rivals.', 'The North American release of the high-velocity sequel.', 'Extreme-G XG2 (USA) features massive jumps and intense weapon combat. With improved visuals and faster engines, it''s the ultimate sci-fi racing challenge for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-world-grand-prix-europe', 'N64', 'F-1 World Grand Prix (Europe)', '1997', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with official 1997 licensing.', 'Win the World Championship as your favorite F1 driver.', 'The European version of the technically acclaimed F1 sim.', 'F-1 World Grand Prix (Europe) features all the real tracks and drivers of the 1997 season. Experience authentic weather effects and pit-stop strategy on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-world-grand-prix-france', 'N64', 'F-1 World Grand Prix (France)', '1997', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with localized French text.', 'Dominate the circuits of the 1997 season in France.', 'The localized French edition of the premier F1 simulator.', 'F-1 World Grand Prix (France) brings the precision of professional racing to French fans. Master the telemetry and car setups to win the title on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-world-grand-prix-germany', 'N64', 'F-1 World Grand Prix (Germany)', '1997', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with localized German text.', 'Outperform the competition in this German F1 edition.', 'The localized German version of the 1997 F1 simulation.', 'F-1 World Grand Prix (Germany) offers a deep look into the world of Formula 1. Enjoy realistic physics and accurate track recreations in this 64-bit sports masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-world-grand-prix-japan', 'N64', 'F-1 World Grand Prix (Japan)', '1997', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with localized Japanese text.', 'Master the Suzuka circuit and win the championship.', 'The Japanese release of the acclaimed F1 racing sim.', 'F-1 World Grand Prix (Japan) provides an authentic 1997 season experience. With its focus on realism and technical detail, it''s a must-play for racing enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-world-grand-prix-usa', 'N64', 'F-1 World Grand Prix (USA)', '1997', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with official 1997 licensing.', 'Overcome the AI and master the 1997 Grand Prix season.', 'The North American release of the landmark F1 racer.', 'F-1 World Grand Prix (USA) set a new standard for sports visuals. Experience real-time damage and dynamic weather in this definitive Formula 1 experience for N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-world-grand-prix-ii-europe-enfrdees', 'N64', 'F-1 World Grand Prix II (Europe) (En,Fr,De,Es)', '1998', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with the 1998 season roster.', 'Win the back-to-back championship in the expanded sequel.', 'The European-exclusive sequel to the F1 hit.', 'F-1 World Grand Prix II (Europe) features the updated 1998 rosters and improved graphics. Experience the thrill of the track with even deeper simulation mechanics on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-x---expansion-kit-japan', 'N64', 'F-Zero X - Expansion Kit (Japan)', '1998', 'Racing', 'Nintendo', '4', 'Futuristic Racing', 'High-speed futuristic racing with a track editor.', 'Create your own courses and race them at 1000 km/h.', 'The 64DD expansion for F-Zero X, localized for Japan.', 'F-Zero X - Expansion Kit (Japan) adds a robust course creator and car editor to the base game. Experience the power of the 64DD with new tracks and music on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-x---expansion-kit-usa', 'N64', 'F-Zero X - Expansion Kit (USA)', '1998', 'Racing', 'Nintendo', '4', 'Futuristic Racing', 'High-speed futuristic racing with a track editor.', 'Design the ultimate death-race circuit in English.', 'A fan-translated or converted version of the 64DD expansion.', 'F-Zero X - Expansion Kit (USA) allows Western players to access the powerful track and craft editors. Push the N64''s limits with custom content in the fastest racer on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-x-europe', 'N64', 'F-Zero X (Europe)', '1998', 'Racing', 'Nintendo', '4', 'Futuristic Racing', 'High-speed futuristic racing with 30 pilots on track.', 'Win the Jack, Queen, and King cups at blistering speeds.', 'The European release of the high-octane racing masterpiece.', 'F-Zero X (Europe) features a rock-solid 60 FPS and intense combat racing. Battle 29 other racers in a struggle for survival and speed in this 64-bit legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-x-japan', 'N64', 'F-Zero X (Japan)', '1998', 'Racing', 'Nintendo', '4', 'Futuristic Racing', 'High-speed futuristic racing with 30 pilots on track.', 'Master the "Death Race" and unlock all secret pilots.', 'The original Japanese release of the legendary F-Zero X.', 'F-Zero X (Japan) introduces the iconic "X" Cup with randomized tracks. Experience the pure adrenaline of futuristic racing with the most responsive controls on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-x-usa', 'N64', 'F-Zero X (USA)', '1998', 'Racing', 'Nintendo', '4', 'Futuristic Racing', 'High-speed futuristic racing with 30 pilots on track.', 'Outrun your rivals and survive the high-altitude tracks.', 'The definitive North American release of F-Zero X.', 'F-Zero X (USA) is famous for its incredible speed and unique "comic book" aesthetic. It remains the gold standard for futuristic racing games on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-pole-position-64-europe-enfrde', 'N64', 'F1 Pole Position 64 (Europe) (En,Fr,De)', '1997', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with 1996 licensing.', 'Win the championship and master the telemetry systems.', 'The European version of the F1 simulator by Ubisoft.', 'F1 Pole Position 64 (Europe) offers a deep racing experience with authentic tracks. Manage your car''s setup and pit strategy to take the checkered flag.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-pole-position-64-usa-enfrde', 'N64', 'F1 Pole Position 64 (USA) (En,Fr,De)', '1997', 'Racing', 'Video System', '2', 'Formula Racing', 'Realistic Formula 1 simulation with 1996 licensing.', 'Become the world champion in the North American circuit.', 'The North American release of the technical F1 title.', 'F1 Pole Position 64 (USA) features realistic handling and official 1996 drivers. Experience the tension of professional racing with detailed 64-bit graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-racing-championship-brazil-enfr', 'N64', 'F1 Racing Championship (Brazil) (En,Fr)', '1999', 'Racing', 'Ubi Soft', '2', 'Formula Racing', 'Realistic Formula 1 simulation with 1999/2000 licensing.', 'Win the Grand Prix in the official Brazilian release.', 'A rare localized version of the F1 Racing Championship.', 'F1 Racing Championship (Brazil) features updated rosters and tracks. Experience high-fidelity F1 racing with localized support for the South American market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-racing-championship-europe-enfrdeesit', 'N64', 'F1 Racing Championship (Europe) (En,Fr,De,Es,It)', '1999', 'Racing', 'Ubi Soft', '2', 'Formula Racing', 'Realistic Formula 1 simulation with 1999/2000 licensing.', 'Conquer the global tracks with high-detail car models.', 'The European multi-language release of the F1 hit.', 'F1 Racing Championship (Europe) is known for its impressive graphics and realistic AI. Navigate the world''s most famous circuits in this advanced N64 racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famista-64-japan', 'N64', 'Famista 64 (Japan)', '1997', 'Sports', 'Namco', '4', 'Baseball', 'Arcade-style baseball with a classic Japanese feel.', 'Lead your team to the victory in the Famista league.', 'A vibrant and fun Japan-exclusive baseball game.', 'Famista 64 (Japan) features the beloved Namco characters and accessible gameplay. Enjoy fast-paced baseball action with a unique 64-bit artistic style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fan-film-sonic-64', 'N64', 'Fan Film Sonic 64', '2021', 'Platformer', 'Independent', '1', 'Fan Game', '3D platforming inspired by cinematic fan productions.', 'Explore custom levels with a cinematic Sonic model.', 'A visually unique Sonic mod for the Mario 64 engine.', 'Fan Film Sonic 64 brings a higher-fidelity Sonic model to the N64. Experience the classic platforming with a fresh, "fan film" inspired aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fan-film-sonic-racing-ocean', 'N64', 'Fan Film Sonic Racing Ocean', '2022', 'Racing', 'Independent', '4', 'Fan Game', '3D racing in a tropical ocean environment.', 'Race through the waves as Sonic in this aquatic mod.', 'A water-focused racing mod featuring Sonic the Hedgehog.', 'Fan Film Sonic Racing Ocean features beautiful water effects and high-speed tracks. Master the maritime racing logic in this creative N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa---road-to-world-cup-98---world-cup-e-no-michi-japan', 'N64', 'FIFA - Road to World Cup 98 - World Cup e no Michi (Japan)', '1997', 'Sports', 'EA Sports', '4', 'Soccer', 'Realistic soccer simulation with road-to-glory mode.', 'Qualify for and win the 1998 World Cup in Japan.', 'The Japanese release of the landmark FIFA 98.', 'FIFA - Road to World Cup 98 (Japan) features an indoor mode and every national team. Experience the most comprehensive soccer game on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa---road-to-world-cup-98-europe-enfrdeesitnlsv', 'N64', 'FIFA - Road to World Cup 98 (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1997', 'Sports', 'EA Sports', '4', 'Soccer', 'Realistic soccer simulation with road-to-glory mode.', 'Choose from 172 national teams and reach the finals.', 'The European multi-language release of the soccer hit.', 'FIFA - Road to World Cup 98 (Europe) is legendary for its soundtrack and deep gameplay. Play through the qualifying rounds in this definitive soccer experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa---road-to-world-cup-98-usa-enfrdeesitnlsv', 'N64', 'FIFA - Road to World Cup 98 (USA) (En,Fr,De,Es,It,Nl,Sv)', '1997', 'Sports', 'EA Sports', '4', 'Soccer', 'Realistic soccer simulation with road-to-glory mode.', 'Lead the USA team to the World Cup trophy.', 'The North American release of the iconic FIFA 98.', 'FIFA - Road to World Cup 98 (USA) revolutionized sports games with its "Road to World Cup" mode. Enjoy 64-bit soccer with real-time tactical changes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-99-europe-enfrdeesitnlptsv', 'N64', 'FIFA 99 (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1998', 'Sports', 'EA Sports', '4', 'Soccer', 'Realistic soccer simulation with refined mechanics.', 'Win the league and master the new skill-move system.', 'The European version of the polished FIFA 99.', 'FIFA 99 (Europe) features faster gameplay and improved animations. With a massive list of clubs and leagues, it''s the peak of 64-bit soccer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-99-usa-enfrdeesitnlptsv', 'N64', 'FIFA 99 (USA) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1998', 'Sports', 'EA Sports', '4', 'Soccer', 'Realistic soccer simulation with refined mechanics.', 'Conquer the Major League Soccer and international cups.', 'The North American release of the acclaimed FIFA 99.', 'FIFA 99 (USA) offers a deep management and gameplay experience. Use the new "sprint" and "shoot" mechanics to dominate the pitch on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-64-europe-enfrde', 'N64', 'FIFA Soccer 64 (Europe) (En,Fr,De)', '1997', 'Sports', 'EA Sports', '4', 'Soccer', '3D soccer simulation with arcade-style movement.', 'Win the international tournament in the European circuit.', 'The first FIFA entry on the Nintendo 64 for Europe.', 'FIFA Soccer 64 (Europe) brought the world''s game into 3D. Experience the early days of 64-bit soccer with varied weather and 4-player multiplayer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-64-usa-enfrde', 'N64', 'FIFA Soccer 64 (USA) (En,Fr,De)', '1997', 'Sports', 'EA Sports', '4', 'Soccer', '3D soccer simulation with arcade-style movement.', 'Lead your favorite country to victory in the USA.', 'The North American debut of the FIFA series on N64.', 'FIFA Soccer 64 (USA) features multiple camera angles and 3D player models. It’s a nostalgic look at the transition of sports games into the 3D era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighter-destiny-2-usa', 'N64', 'Fighter Destiny 2 (USA)', '2000', 'Fighting', 'Eidos Interactive', '2', '3D Fighting', '3D fighting game with a point-based scoring system.', 'Master the "Technical" and "Counter" moves to win.', 'The North American sequel to Fighters Destiny.', 'Fighter Destiny 2 (USA) features an expanded roster and refined point system. Win matches by knocking out, throwing, or ringing out your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-destiny-europe', 'N64', 'Fighters Destiny (Europe)', '1998', 'Fighting', 'Eidos Interactive', '2', '3D Fighting', '3D fighting game with a point-based scoring system.', 'Score 10 points using various fighting techniques.', 'The European release of the innovative 3D brawler.', 'Fighters Destiny (Europe) breaks the traditional "health bar" mold. Focus on skill and variety to earn points and defeat the world''s best fighters on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-destiny-france', 'N64', 'Fighters Destiny (France)', '1998', 'Fighting', 'Eidos Interactive', '2', '3D Fighting', '3D fighting game with localized French text.', 'Defeat the masters of martial arts in this French edition.', 'The localized French version of the innovative fighter.', 'Fighters Destiny (France) brings the unique point-based combat to French fans. Master the grappling and striking systems to claim the championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-destiny-germany', 'N64', 'Fighters Destiny (Germany)', '1998', 'Fighting', 'Eidos Interactive', '2', '3D Fighting', '3D fighting game with localized German text.', 'Rise through the ranks in this German fighting edition.', 'The localized German version of the Fighters Destiny hit.', 'Fighters Destiny (Germany) offers a deep and strategic fighting experience. Use the training mode to learn every move and dominate the 64-bit arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-destiny-usa', 'N64', 'Fighters Destiny (USA)', '1998', 'Fighting', 'Eidos Interactive', '2', '3D Fighting', '3D fighting game with a point-based scoring system.', 'Unlock the secret "Joker" and "Master" characters.', 'The original North American release of Fighters Destiny.', 'Fighters Destiny (USA) is a cult classic known for its unique mechanics. It’s one of the most balanced and original fighting games on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-cup-japan', 'N64', 'Fighting Cup (Japan)', '1997', 'Fighting', 'Nichibutsu', '2', 'Arcade Fighting', '3D fighting game with a point-based scoring system.', 'Conquer the tournament in the Japanese version.', 'The Japanese release of the fighter known as Fighters Destiny.', 'Fighting Cup (Japan) features the same deep mechanics and character customization. Experience the origin of the point-based 3D brawler on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-force-64-europe', 'N64', 'Fighting Force 64 (Europe)', '1999', 'Action', 'Core Design', '2', 'Beat ''em Up', 'Side-scrolling 3D beat ''em up with environmental weapons.', 'Fight your way through the city to stop Dr. Dex.', 'The European version of the gritty urban brawler.', 'Fighting Force 64 (Europe) features four playable characters and fully destructible objects. Smash cars and use pipes to defeat the syndicate on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-force-64-usa', 'N64', 'Fighting Force 64 (USA)', '1999', 'Action', 'Core Design', '2', 'Beat ''em Up', 'Side-scrolling 3D beat ''em up with environmental weapons.', 'Stop the apocalypse in this North American action hit.', 'The North American release of the 3D brawler.', 'Fighting Force 64 (USA) brings the "Final Fight" spirit to 3D. Battle through 22 levels of intense action with a variety of weapons and special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flying-dragon-europe', 'N64', 'Flying Dragon (Europe)', '1997', 'Fighting', 'Culture Brain', '2', 'Martial Arts', '2D/3D fighting game with a "Virtual Culture" RPG mode.', 'Win the tournament and grow your fighter in the quest.', 'The European release of the unique hybrid fighter.', 'Flying Dragon (Europe) features two distinct gameplay styles: SD characters and realistic fighters. Master the RPG-lite "Quest Mode" to unlock rare items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flying-dragon-usa', 'N64', 'Flying Dragon (USA)', '1997', 'Fighting', 'Culture Brain', '2', 'Martial Arts', '2D/3D fighting game with a "Virtual Culture" RPG mode.', 'Collect the "Secret Scrolls" to enhance your techniques.', 'The North American release of the multifaceted fighter.', 'Flying Dragon (USA) is a unique blend of combat and character progression. Choose between the whimsical SD mode or the technical "Virtual" mode on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forsaken-64-europe-enfresit', 'N64', 'Forsaken 64 (Europe) (En,Fr,Es,It)', '1998', 'Shooter', 'Iguana Entertainment', '4', 'First-Person Shooter', '360-degree first-person shooter with hover-crafts.', 'Navigate claustrophobic tunnels and eliminate all scavengers.', 'The European multi-language release of the sci-fi shooter.', 'Forsaken 64 (Europe) offers true 3D freedom of movement. Battle through complex underground bases with a wide array of devastating futuristic weapons on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forsaken-64-germany', 'N64', 'Forsaken 64 (Germany)', '1998', 'Shooter', 'Iguana Entertainment', '4', 'First-Person Shooter', '360-degree first-person shooter with localized assets.', 'Survive the post-apocalyptic zones in this German edition.', 'The localized German version of the high-speed FPS.', 'Forsaken 64 (Germany) features the same intense gravity-defying combat optimized for the German market. Master the flight controls and dominate the 64-bit arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forsaken-64-usa', 'N64', 'Forsaken 64 (USA)', '1998', 'Shooter', 'Iguana Entertainment', '4', 'First-Person Shooter', '360-degree first-person shooter in a futuristic Earth.', 'Complete the ultimate scavenger hunt in the North American version.', 'The definitive North American release of Forsaken.', 'Forsaken 64 (USA) is a technical showcase for the N64, featuring incredible lighting effects and fast-paced multiplayer. It’s the ultimate 3D aerial combat experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fox-sports-college-hoops-99-usa', 'N64', 'Fox Sports College Hoops ''99 (USA)', '1999', 'Sports', 'Beam Software', '4', 'Basketball', 'Realistic college basketball simulation with 1999 rosters.', 'Lead your university to the NCAA championship victory.', 'A deep and authentic college basketball title for the N64.', 'Fox Sports College Hoops ''99 (USA) features real teams, players, and coaching strategies. Experience the madness of March with official licensing and 64-bit graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freeing-marty-the-thwomp-in-mario-kart-64', 'N64', 'Freeing Marty the Thwomp in Mario Kart 64', '2023', 'Racing', 'Independent', '4', 'ROM Hack', 'Puzzle-adventure/mod featuring a mission in MK64.', 'Solve the clues to free the trapped Thwomp in the track.', 'A creative story-based mod within the Mario Kart 64 engine.', 'Freeing Marty the Thwomp is a unique fan mission. Explore the tracks of MK64 from a new perspective to complete this charming community-made objective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-2-usa-rev-a-proto', 'N64', 'Frogger 2 (USA) (Rev A) (Proto)', '1999', 'Platformer', 'Blitz Games', '2', 'Action Platformer', 'Classic arcade platforming with updated 3D graphics.', 'Guide Frogger safely through dangerous traffic and rivers.', 'A rare prototype/revision of the unreleased sequel for N64.', 'Frogger 2 (USA) (Rev A) (Proto) provides a glimpse into the 3D evolution of the classic franchise. Experience new mechanics and environments in this "lost" N64 build.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-64', 'N64', 'Frogger 64', '1997', 'Platformer', 'Blitz Games', '2', 'Action Platformer', 'Classic arcade platforming with a full 3D makeover.', 'Navigate through 3D environments to reach the finish line.', 'The first 3D entry of the Frogger series on the N64.', 'Frogger 64 brings the retro gameplay into a new dimension. Dodge hazards and collect flies across diverse worlds in this faithful 64-bit remake of the arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('furious-sonic-64', 'N64', 'Furious Sonic 64', '2021', 'Platformer', 'Independent', '1', 'Fan Game', 'High-speed 3D platforming with an aggressive theme.', 'Race through levels as a faster, "furious" version of Sonic.', 'A high-velocity character mod for the Mario 64 engine.', 'Furious Sonic 64 focuses on pure speed and agility. Navigate custom levels with increased momentum and a custom model in this intense N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon---fuurai-no-shiren-2---oni-shuurai!-shiren-jou!-japan', 'N64', 'Fushigi no Dungeon - Fuurai no Shiren 2 - Oni Shuurai! Shiren Jou! (Japan)', '2000', 'RPG', 'Chunsoft', '1', 'Roguelike', 'Turn-based roguelike with deep RPG elements.', 'Build your castle and stop the Oni invasion.', 'The critically acclaimed Japan-exclusive Shiren sequel.', 'Fushigi no Dungeon - Fuurai no Shiren 2 is one of the best looking N64 games. Experience a deep, challenging dungeon-crawler with beautiful 2D/3D hybrid visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gasp!!-fighters-nextream-europe', 'N64', 'G.A.S.P!! Fighters'' NEXTream (Europe)', '1998', 'Fighting', 'KONAMI', '2', '3D Fighting', '3D weapon-based fighting game with customization.', 'Master your fighter''s skills and defeat the NEXTream.', 'The European release of the technical 3D fighter.', 'G.A.S.P!! Fighters'' NEXTream (Europe) features a unique training system. Build your own moveset and battle in futuristic arenas in this 64-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gasp!!-fighters-nextream-japan', 'N64', 'G.A.S.P!! Fighters'' NEXTream (Japan)', '1998', 'Fighting', 'KONAMI', '2', '3D Fighting', '3D weapon-based fighting game with customization.', 'Rise to the top of the Japanese fighting circuit.', 'The original Japanese release of the G.A.S.P!! fighter.', 'G.A.S.P!! Fighters'' NEXTream (Japan) offers a deep character progression system and fast-paced 3D combat. Experience the origin of this cult-classic fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gadget-the-wolf-64-playable', 'N64', 'Gadget The Wolf 64 Playable', '2020', 'Platformer', 'Independent', '1', 'Fan Game', '3D platforming featuring a custom wolf protagonist.', 'Explore the levels as the high-tech Gadget the Wolf.', 'A character-swap mod with a custom 3D model.', 'Gadget The Wolf 64 Playable introduces a new hero to the SM64 engine. Use custom animations and his unique look to conquer the castle in this fan-made project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamebooster-64-europe-v11-unl', 'N64', 'GameBooster 64 (Europe) (v1.1) (Unl)', '1999', 'Utility', 'Unlicensed', '1', 'System Tool', 'Utility tool for playing Game Boy games on the N64.', 'Emulate and play classic handheld games on your TV.', 'An unlicensed European utility for N64 consoles.', 'GameBooster 64 (Europe) allows you to bridge the gap between GB and N64. Experience your favorite handheld classics with enhanced stability on the big screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamebooster-64-usa-v11-unl', 'N64', 'GameBooster 64 (USA) (v1.1) (Unl)', '1999', 'Utility', 'Unlicensed', '1', 'System Tool', 'Utility tool for playing Game Boy games on the N64.', 'Access your Game Boy library using the N64 hardware.', 'The unlicensed North American release of the emulator tool.', 'GameBooster 64 (USA) provides a convenient way to play classic 8-bit games. It’s a nostalgic utility that highlights the versatility of the N64 era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamma-64-demo-v092', 'N64', 'Gamma 64 Demo v0.92', '2021', 'Tech Demo', 'Independent', '1', 'Engine Demo', 'Technical 3D platforming with custom physics.', 'Test the limits of the SM64 engine in this early demo.', 'A technical showcase mod for future SM64 projects.', 'Gamma 64 Demo v0.92 features custom assets and experimental physics. Experience the cutting edge of N64 modding in this atmospheric and technical demo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamma64-v110', 'N64', 'Gamma64 V1.10', '2022', 'Tech Demo', 'Independent', '1', 'Engine Demo', 'Expanded 3D platforming with polished level design.', 'Conquer the custom challenges in this finalized build.', 'The complete version of the Gamma64 modding project.', 'Gamma64 V1.10 offers high-quality custom levels and a unique aesthetic. It stands as a testament to the creativity of the N64 ROM hacking community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon---dero-dero-douchuu-obake-tenkomori-japan', 'N64', 'Ganbare Goemon - Dero Dero Douchuu Obake Tenkomori (Japan)', '1998', 'Action', 'Konami', '2', 'Action Adventure', '2.5D/3D platformer with traditional Japanese humor.', 'Stop the ghost invasion across a colorful Japan.', 'The Japanese sequel to the first N64 Goemon adventure.', 'Dero Dero Douchuu features a return to 2D-style platforming with 3D models. Experience the incredible soundtrack and wacky humor that the series is famous for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon---neo-momoyama-bakufu-no-odori-japan', 'N64', 'Ganbare Goemon - Neo Momoyama Bakufu no Odori (Japan)', '1997', 'Action', 'Konami', '2', 'Action Adventure', '3D action-adventure with open-world exploration.', 'Save a 3D feudal Japan from the "Neo Momoyama" threat.', 'The legendary Japanese version of Mystical Ninja.', 'Neo Momoyama Bakufu no Odori is an N64 masterpiece. Explore towns, pilot giant robots, and enjoy a full vocal soundtrack in this epic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare!-nippon!-olympics-2000-japan', 'N64', 'Ganbare! Nippon! Olympics 2000 (Japan)', '2000', 'Sports', 'KONAMI', '4', 'Olympics', 'Sports simulation with multiple Olympic events.', 'Win the gold medal for Japan in the 2000 Sydney Games.', 'The Japanese release of the Konami Olympics title.', 'Ganbare! Nippon! Olympics 2000 features realistic athletics and 4-player multiplayer. Compete in track, field, and swimming events on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield:-desolation', 'N64', 'Garfield: Desolation', '2022', 'Adventure', 'Independent', '1', 'Fan Game', 'Surreal horror-platforming with a dark Garfield theme.', 'Survive the "desolate" world of the famous orange cat.', 'A creepy and creative "creepypasta" style mod for SM64.', 'Garfield: Desolation turns the Mushroom Kingdom into a nightmare. Experience surreal horror and dark humor as you navigate this unique N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-legends-europe', 'N64', 'Gauntlet Legends (Europe)', '1999', 'Action', 'Midway', '4', 'Arcade Action', '3D hack-and-slash with RPG progression and co-op.', 'Defeat Skorne and recover the runestones in Europe.', 'The European release of the legendary arcade dungeon-crawler.', 'Gauntlet Legends (Europe) features four-player simultaneous action. Level up your hero and battle through hordes of enemies in this definitive N64 port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-legends-japan', 'N64', 'Gauntlet Legends (Japan)', '1999', 'Action', 'Midway', '4', 'Arcade Action', '3D hack-and-slash with RPG progression and co-op.', 'Conquer the Japanese dungeons with your warrior squad.', 'The Japanese release of the high-fantasy brawler.', 'Gauntlet Legends (Japan) brings the classic arcade teamwork to Japan. Choose from the Warrior, Valkyrie, Wizard, or Archer and save the realm on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-legends-usa', 'N64', 'Gauntlet Legends (USA)', '1999', 'Action', 'Midway', '4', 'Arcade Action', '3D hack-and-slash with RPG progression and co-op.', 'Reach the final level and destroy the demon lord Skorne.', 'The definitive North American release of Gauntlet Legends.', 'Gauntlet Legends (USA) is an N64 essential. With its addictive loop of collecting gold and power-ups, it remains one of the best multiplayer games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gay-baby-road', 'N64', 'Gay Baby Road', '2021', 'Racing', 'Independent', '1', 'Fan Game', '3D racing mod with a focus on Internet humor.', 'Race through "bizzare" and "unfair" tracks to win.', 'A humorous and challenging Mario Kart 64 modification.', 'Gay Baby Road is a meme-heavy mod that tests your patience. Experience weird shortcuts and intentional "soft-locks" in this funny N64 community joke.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geno-pack', 'N64', 'Geno Pack', '2020', 'Utility', 'Independent', '1', 'ROM Hack', '3D platforming featuring the Super Mario RPG character.', 'Play as Geno with custom moves and projectiles.', 'A high-quality character pack mod for Mario 64.', 'Geno Pack brings the fan-favorite puppet hero to 3D. Use his signature Star Gun and special moves to explore the castle in this impressive N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('getter-love!!-cho-renai-party-game-japan', 'N64', 'Getter Love!! Cho Renai Party Game (Japan)', '1997', 'Party', 'Game Freak', '4', 'Dating Sim', 'Dating simulation with party game mechanics.', 'Win the heart of your favorite girl through minigames.', 'A unique and rare Japan-exclusive "love" party game.', 'Getter Love!! features 4-player competitive dating sims. It’s a creative mix of board game and romance that shows the variety of the Japanese N64 library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex-3---deep-cover-gecko-europe-enesit', 'N64', 'Gex 3 - Deep Cover Gecko (Europe) (En,Es,It)', '1999', 'Platformer', 'Crystal Dynamics', '2', 'Action Platformer', '3D platforming with a focus on movie and TV parodies.', 'Rescue the secret agents from the media dimension.', 'The European release of Gex''s third 3D adventure.', 'Gex 3 - Deep Cover Gecko (Europe) is packed with wit and variety. From spy missions to superhero parodies, help Gex save the world on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex-3---deep-cover-gecko-europe-frde', 'N64', 'Gex 3 - Deep Cover Gecko (Europe) (Fr,De)', '1999', 'Platformer', 'Crystal Dynamics', '2', 'Action Platformer', '3D platforming with localized French and German audio.', 'Stop Rez once and for all in this localized edition.', 'The localized European version of Gex''s swan song.', 'Gex 3 (Fr/De) features localized voice acting for Gex''s famous one-liners. Experience the movie-themed worlds with specialized localization for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex-3---deep-cover-gecko-usa', 'N64', 'Gex 3 - Deep Cover Gecko (USA)', '1999', 'Platformer', 'Crystal Dynamics', '2', 'Action Platformer', '3D platforming with dozens of costumes and abilities.', 'Stop the evil Rez from taking over the media world.', 'The North American release of Gex''s biggest 3D title.', 'Gex 3 - Deep Cover Gecko (USA) features massive levels and a variety of vehicles. It’s a high-energy platformer that parodies pop culture with N64 charm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex-64---enter-the-gecko-europe', 'N64', 'Gex 64 - Enter the Gecko (Europe)', '1998', 'Platformer', 'Crystal Dynamics', '2', 'Action Platformer', '3D platforming with a "Media" themed hub world.', 'Recover the TV remotes and defeat Rez in the N64 debut.', 'The European version of Gex''s first full 3D quest.', 'Gex 64 - Enter the Gecko features themed worlds like "Scream TV" and "Toon TV." Use Gex''s tail and tongue to explore this satirical 64-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex-64---enter-the-gecko-usa', 'N64', 'Gex 64 - Enter the Gecko (USA)', '1998', 'Platformer', 'Crystal Dynamics', '2', 'Action Platformer', '3D platforming with dozens of pop-culture one-liners.', 'Collect every remote and unlock the secret levels.', 'The North American release of Gex''s 3D breakthrough.', 'Gex 64 - Enter the Gecko (USA) is a love letter to 90s television. With its creative level design and witty dialogue, it remains a cult classic on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glover-europe-enfrde', 'N64', 'Glover (Europe) (En,Fr,De)', '1998', 'Platformer', 'Interactive Studios', '2', 'Puzzle Platformer', '3D puzzle-platforming with ball-rolling mechanics.', 'Guide Glover the glove through magical worlds to save his friend.', 'The European release of the innovative ball-rolling adventure.', 'Glover (Europe) features unique physics and puzzle solving. Manipulate a magical ball to navigate through dangerous environments in this creative N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glover-usa', 'N64', 'Glover (USA)', '1998', 'Platformer', 'Interactive Studios', '2', 'Puzzle Platformer', '3D puzzle-platforming with ball-rolling mechanics.', 'Restore the crystals and defeat the evil Cross-Stitch.', 'The definitive North American release of Glover.', 'Glover (USA) is known for its challenging difficulty and original concept. Master the six different ball forms to conquer the diverse worlds on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glover-2-usa-proto', 'N64', 'Glover 2 (USA) (Proto)', '1999', 'Platformer', 'Interactive Studios', '2', 'Puzzle Platformer', '3D puzzle-platforming with a magical ball.', 'Explore unfinished levels and test new ball mechanics.', 'A playable prototype of the canceled sequel to Glover.', 'Glover 2 (USA) (Proto) gives fans a glimpse of what could have been. Experience new transformations and updated physics in this fascinating "lost" N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glover-2-usa-proto-early', 'N64', 'Glover 2 (USA) (Proto) (early)', '1999', 'Platformer', 'Interactive Studios', '2', 'Puzzle Platformer', '3D puzzle-platforming with early dev assets.', 'Navigate through basic geometry and early level concepts.', 'An extremely early developmental build of Glover 2.', 'This "Early" Proto of Glover 2 is a technical treasure. It showcases the foundational work on the sequel before its cancellation, featuring raw N64 code and assets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goemon---mononoke-sugoroku-japan', 'N64', 'Goemon - Mononoke Sugoroku (Japan)', '1999', 'Board Game', 'KONAMI', '4', 'Sugoroku', 'Digital board game with card-battle elements.', 'Win the Sugoroku matches using Mononoke summons.', 'A Japan-exclusive board game featuring the Goemon cast.', 'Goemon - Mononoke Sugoroku combines strategy and luck. Collect spirits and outsmart your rivals in this beautifully animated Japanese N64 exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goemons-great-adventure-usa', 'N64', 'Goemon''s Great Adventure (USA)', '1998', 'Platformer', 'KONAMI', '2', 'Action Platformer', '2.5D side-scrolling platformer with 4-player co-op.', 'Defeat Bismaru and her mechanical ghost army.', 'The acclaimed North American sequel to Mystical Ninja.', 'Goemon''s Great Adventure is considered one of the best platformers on the system. With a day/night cycle and incredible music, it''s a 64-bit masterpiece of style and fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gold-sonic-master-64', 'N64', 'Gold Sonic Master 64', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming featuring a shiny custom Sonic model.', 'Collect stars at high speed as a golden-colored Sonic.', 'A character-swap mod featuring "Gold Sonic" for SM64.', 'Gold Sonic Master 64 adds a metallic flair to the classic platforming. Use Sonic’s speed and custom animations to master the N64 castle in style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-nugget-64-usa', 'N64', 'Golden Nugget 64 (USA)', '1998', 'Casino', 'Westwood', '4', 'Casino', 'Realistic casino simulation with multiple table games.', 'Win big at poker, blackjack, and roulette.', 'A comprehensive gambling simulator for the N64.', 'Golden Nugget 64 (USA) brings the Las Vegas experience home. With realistic odds and multiple games, it’s a detailed and fun simulation of high-stakes gambling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goombas-easter-egg-hunt', 'N64', 'Goomba''s Easter Egg Hunt', '2022', 'Platformer', 'Independent', '1', 'Fan Game', '3D platforming with a festive holiday theme.', 'Help the Goomba find every hidden Easter Egg in the level.', 'A charming holiday-themed mod for the Mario 64 engine.', 'Goomba''s Easter Egg Hunt features a custom protagonist and colorful assets. Explore a peaceful environment in this creative and family-friendly N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gourmet-guys-1000iq-food-quiz', 'N64', 'Gourmet Guy''s 1000IQ Food Quiz', '2023', 'Quiz', 'Independent', '1', 'Trivia', 'Trivia and puzzle-solving based on Paper Mario.', 'Answer Gourmet Guy''s food-related questions correctly.', 'A humorous and challenging quiz mod for Mario 64.', 'Gourmet Guy''s 1000IQ Food Quiz tests your knowledge of the franchise. Solve logic puzzles and prove your "IQ" in this funny N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gravity-swap-64-v1031', 'N64', 'Gravity Swap 64 v1.0.3.1', '2022', 'Puzzle', 'Independent', '1', 'Puzzle Action', '3D platforming with gravity-flipping mechanics.', 'Navigate levels by switching the direction of gravity.', 'An innovative technical mod that changes core physics.', 'Gravity Swap 64 v1.0.3.1 challenges everything you know about platforming. Walk on ceilings and solve vertical puzzles in this clever N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gruntys-mansion-20', 'N64', 'Grunty''s Mansion 2.0', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming in a Banjo-themed mansion.', 'Explore Gruntilda’s renovated lair and find every Jiggy.', 'A high-quality Banjo-Kazooie overhaul mod.', 'Grunty''s Mansion 2.0 reimagines the iconic hub world with new challenges. Experience a "remixed" adventure with custom puzzles on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gt64---championship-edition-europe-enfrde', 'N64', 'GT64 - Championship Edition (Europe) (En,Fr,De)', '1998', 'Racing', 'Imagineer', '2', 'Simulation Racing', 'Professional touring car racing with licensed GT vehicles.', 'Win the GT Championship across international tracks.', 'The European version of the technical GT racing title.', 'GT64 - Championship Edition (Europe) features realistic car tuning and physics. Master the corners and climb the ranks in this polished 64-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gt64---championship-edition-usa', 'N64', 'GT64 - Championship Edition (USA)', '1998', 'Racing', 'Imagineer', '2', 'Simulation Racing', 'Professional touring car racing with licensed GT vehicles.', 'Conquer the American circuits and unlock secret cars.', 'The North American release of the GT64 simulation.', 'GT64 - Championship Edition (USA) offers a deep career mode and smooth frame rates. It’s an authentic racing experience that captures the era of GT touring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guitar-hero-64', 'N64', 'Guitar Hero 64', '2020', 'Music', 'Independent', '2', 'Rhythm', 'Rhythm-based gameplay with a focus on rock music.', 'Hit the notes in time with the custom rock soundtrack.', 'A creative rhythm-game mod for the N64.', 'Guitar Hero 64 brings the plastic-guitar phenomenon to the N64 controller. Experience custom tracks and responsive rhythm gameplay in this impressive fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('halloween-at-boos', 'N64', 'Halloween at Boo''s', '2021', 'Adventure', 'Independent', '1', 'Fan Game', '3D platforming in a spooky, haunted castle environment.', 'Survive the Halloween night at Boo''s mansion.', 'A spooky-themed visual overhaul mod for Mario 64.', 'Halloween at Boo''s features custom textures and eerie lighting. Explore the haunted grounds and collect spooky stars in this atmospheric N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hallowoomy-on-spoopy-island-v11', 'N64', 'Hallowoomy on Spoopy Island (v1.1)', '2022', 'Adventure', 'Independent', '1', 'Fan Game', '3D platforming on a stylized "Spoopy" island.', 'Explore the mysterious island and solve holiday puzzles.', 'A cute and spooky Halloween-themed mod.', 'Hallowoomy on Spoopy Island (v1.1) is a polished adventure with custom models and a festive atmosphere. A perfect N64 run for the Halloween season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-monogatari-64-japan', 'N64', 'Hamster Monogatari 64 (Japan)', '1997', 'Simulation', 'Culture Brain', '1', 'Pet Simulation', 'Virtual pet simulation featuring realistic hamsters.', 'Raise, train, and play with your custom pet hamster.', 'A charming Japan-exclusive life simulator.', 'Hamster Monogatari 64 brings the "Tamagotchi" style to 3D. Care for your hamster and enter competitions in this cute and rare Japanese N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harukanaru-augusta---masters-98-japan', 'N64', 'Harukanaru Augusta - Masters ''98 (Japan)', '1998', 'Sports', 'T&E Soft', '4', 'Golf', 'Realistic golf simulation with professional licensing.', 'Win the Masters tournament at the legendary Augusta.', 'A high-fidelity Japanese golf title with real courses.', 'Harukanaru Augusta - Masters ''98 features advanced terrain physics and official licensing. It’s a sophisticated sports sim for the Nintendo 64 enthusiast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-64-usa', 'N64', 'Harvest Moon 64 (USA)', '1999', 'Simulation', 'Natsume', '1', 'Farming', 'Farming simulation and social management.', 'Save the family farm and start a family in Flowerbud Village.', 'The definitive North American release of the farming hit.', 'Harvest Moon 64 (USA) is a cult classic known for its deep social mechanics and addictive gameplay loop. It remains one of the most beloved "lifestyle" games on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hazy-maze-city', 'N64', 'Hazy Maze City', '2023', 'Adventure', 'Independent', '1', 'Fan Game', '3D platforming in a dense, fog-filled industrial city.', 'Find the stars hidden among the skyscrapers and haze.', 'A moody urban-themed custom world for Mario 64.', 'Hazy Maze City expands on the "Hazy Maze Cave" aesthetic with a vertical, metropolitan twist. Navigate through the smog in this challenging N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heiwa-pachinko-world-64-japan', 'N64', 'Heiwa Pachinko World 64 (Japan)', '1997', 'Casino', 'Athena', '1', 'Pachinko', 'Pachinko simulation with multiple themed machines.', 'Master the art of the silver ball in this realistic sim.', 'A specialized Japan-exclusive gambling title.', 'Heiwa Pachinko World 64 features detailed machine physics and various bonus modes. Experience the unique culture of Japanese Pachinko on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hercules---the-legendary-journeys-europe-enfrdeesitnl', 'N64', 'Hercules - The Legendary Journeys (Europe) (En,Fr,De,Es,It,Nl)', '1998', 'Action', 'Titus', '2', 'Action Adventure', '3D action-adventure based on the hit TV series.', 'Complete mythological quests as the legendary Hercules.', 'The European multi-language release of the action title.', 'Hercules - The Legendary Journeys features open-world elements and combat. Battle hydras and save villagers in this epic mythological N64 journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hercules---the-legendary-journeys-usa', 'N64', 'Hercules - The Legendary Journeys (USA)', '1998', 'Action', 'Titus', '2', 'Action Adventure', '3D action-adventure with a focus on combat and exploration.', 'Defeat the evil Hera and prove your worth as a hero.', 'The North American release of the Hercules adventure.', 'Hercules - The Legendary Journeys (USA) captures the spirit of the show. Explore ancient Greece and use your strength to solve puzzles in this classic brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hexen-europe', 'N64', 'Hexen (Europe)', '1997', 'FPS', 'Raven Software', '4', 'Shooter', 'First-person action-adventure with RPG elements.', 'Choose your class (Warrior, Mage, Cleric) and defeat Korax.', 'The European version of the dark-fantasy FPS.', 'Hexen (Europe) features non-linear level design and intense weapon combat. Use magic and steel to survive the world of Cronos on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hexen-france', 'N64', 'Hexen (France)', '1997', 'FPS', 'Raven Software', '4', 'Shooter', 'First-person action-adventure with localized French text.', 'Stop the Serpent Rider in this localized French edition.', 'The localized French version of the Hexen port.', 'Hexen (France) brings the gritty, medieval atmosphere to French fans. Experience the unique hub-based world structure of this 64-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hexen-germany', 'N64', 'Hexen (Germany)', '1997', 'FPS', 'Raven Software', '4', 'Shooter', 'First-person action-adventure with localized German text.', 'Solve the ancient puzzles of Cronos in Germany.', 'The localized German version of the dark-fantasy title.', 'Hexen (Germany) offers the same deep gameplay and atmospheric horror optimized for the N64 with localized text and menus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hexen-japan', 'N64', 'Hexen (Japan)', '1997', 'FPS', 'Raven Software', '4', 'Shooter', 'First-person action-adventure with localized Japanese text.', 'Conquer the dark forces in this Japanese port.', 'The Japanese release of the atmospheric fantasy FPS.', 'Hexen (Japan) features the iconic three-class system and complex level architecture. Master the spells and weapons to defeat the final boss on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hexen-usa', 'N64', 'Hexen (USA)', '1997', 'FPS', 'Raven Software', '4', 'Shooter', 'First-person action-adventure with hub-based exploration.', 'Navigate the 7 portals and defeat the dark master.', 'The definitive North American release of the N64 port.', 'Hexen (USA) is famous for its atmospheric sound design and challenging puzzles. It’s a standout title that blends FPS action with deep exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hey-you-pikachu!-usa', 'N64', 'Hey You, Pikachu! (USA)', '2000', 'Simulation', 'Ambrella', '1', 'Voice Interaction', 'Voice-recognition simulation featuring Pikachu.', 'Talk to Pikachu and build a friendship through various tasks.', 'The innovative N64 title featuring the Voice Recognition Unit.', 'Hey You, Pikachu! (USA) was ahead of its time. Use the N64 microphone to give commands and interact with the world''s most famous Pokémon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiryuu-no-ken-twin-japan', 'N64', 'Hiryuu no Ken Twin (Japan)', '1997', 'Fighting', 'Culture Brain', '2', '3D Fighting', '2D/3D fighting game with localized Japanese text.', 'Win the tournament in this original Japanese release.', 'The Japanese version of the fighter Flying Dragon.', 'Hiryuu no Ken Twin features two distinct modes: a traditional 2D fighter and a modern 3D brawler. Experience the best of both worlds on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hockey-star-64', 'N64', 'Hockey Star 64', '2000', 'Sports', 'Ice', '2', 'Hockey', 'Realistic ice hockey simulation with arcade elements.', 'Win the cup and master the physics of the ice.', 'A technical hockey title for the Nintendo 64.', 'Hockey Star 64 features fast-paced action and 4-player multiplayer. Experience the tension of the rink with smooth animations and responsive N64 controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holiday-highlands', 'N64', 'Holiday Highlands', '2022', 'Platformer', 'Independent', '1', 'Fan Game', '3D platforming in a festive, winter-themed world.', 'Collect the holiday stars in a beautiful snowy mountain.', 'A cheerful and cozy Christmas-themed mod for SM64.', 'Holiday Highlands features custom snowy assets and a festive soundtrack. Master the icy platforming in this beautifully designed N64 fan expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holy-magic-century-europe', 'N64', 'Holy Magic Century (Europe)', '1998', 'RPG', 'Kemco', '1', 'Tactical RPG', 'Turn-based RPG with elemental spell-casting.', 'Find your father and master the four elements of magic.', 'The European version of the N64 RPG "Quest 64."', 'Holy Magic Century (Europe) offers a unique spell-leveling system. Explore the land of Celtland and customize your magical abilities in this vibrant 3D role-playing adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holy-magic-century-france', 'N64', 'Holy Magic Century (France)', '1998', 'RPG', 'Kemco', '1', 'Tactical RPG', 'Turn-based RPG with localized French text.', 'Rescue the world of Celtland in this French edition.', 'The localized French release of the elemental N64 RPG.', 'Holy Magic Century (France) brings the journey of Brian to French fans. Master Earth, Wind, Fire, and Water magic to defeat the dark mages on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holy-magic-century-germany', 'N64', 'Holy Magic Century (Germany)', '1998', 'RPG', 'Kemco', '1', 'Tactical RPG', 'Turn-based RPG with localized German text.', 'Solve the mysteries of the spirit world in Germany.', 'The localized German version of the Quest 64 experience.', 'Holy Magic Century (Germany) features the full 3D adventure with German menus and dialogue. Experience the origin of the elemental RPG genre on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby-64-japan', 'N64', 'Hoshi no Kirby 64 (Japan)', '2000', 'Platformer', 'HAL Laboratory', '4', '3D Platformer', '2.5D side-scrolling platforming with power combos.', 'Collect the Crystal Shards and save Ripple Star.', 'The original Japanese release of Kirby''s 64-bit debut.', 'Hoshi no Kirby 64 (Japan) introduces the revolutionary "Power Combo" system. Mix two abilities to create unique weapons in this colorful and charming classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby-64-japan-rev-a', 'N64', 'Hoshi no Kirby 64 (Japan) (Rev A)', '2000', 'Platformer', 'HAL Laboratory', '4', '3D Platformer', '2.5D platforming with technical refinements.', 'Stop Dark Matter from consuming the galaxy.', 'An updated Japanese revision of Kirby 64.', 'Hoshi no Kirby 64 (Japan) (Rev A) provides minor bug fixes to the original release, ensuring a smoother platforming experience through the various themed planets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby-64-japan-rev-b', 'N64', 'Hoshi no Kirby 64 (Japan) (Rev B)', '2000', 'Platformer', 'HAL Laboratory', '4', '3D Platformer', '2.5D platforming with final logic polish.', 'Recover all the shards to see the true ending.', 'A secondary Japanese revision for the Kirby 64 title.', 'Hoshi no Kirby 64 (Japan) (Rev B) offers optimized performance and corrected event triggers, making it a highly stable version for N64 collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby-64-japan-rev-c', 'N64', 'Hoshi no Kirby 64 (Japan) (Rev C)', '2000', 'Platformer', 'HAL Laboratory', '4', '3D Platformer', '2.5D platforming with ultimate technical stability.', 'Defeat Zero Two with the most refined build.', 'The final technical revision for the Japanese Kirby 64.', 'Hoshi no Kirby 64 (Japan) (Rev C) is the most polished version of Kirby''s N64 adventure, fixing rare glitches and optimizing the 64-bit visuals for the best experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hot-wheels---turbo-racing-europe-enfrde', 'N64', 'Hot Wheels - Turbo Racing (Europe) (En,Fr,De)', '1999', 'Racing', 'Stormfront Studios', '2', 'Arcade Racing', 'High-speed arcade racing with stunts and tricks.', 'Win races and perform mid-air flips to earn turbo.', 'The European multi-language release of the Hot Wheels hit.', 'Hot Wheels - Turbo Racing (Europe) features a killer soundtrack and 40 classic cars. Fly through loops and crush the competition in this high-energy N64 racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hot-wheels---turbo-racing-usa', 'N64', 'Hot Wheels - Turbo Racing (USA)', '1999', 'Racing', 'Stormfront Studios', '2', 'Arcade Racing', 'High-speed arcade racing with stunts and tricks.', 'Unlock the "Twin Mill" and other legendary cars.', 'The definitive North American release of the Hot Wheels racer.', 'Hot Wheels - Turbo Racing (USA) is pure arcade fun. Master the stunt-based turbo system and discover secret shortcuts in this fan-favorite racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hsv-adventure-racing!-australia', 'N64', 'HSV Adventure Racing! (Australia)', '2002', 'Racing', 'Krome Studios', '2', 'Off-Road Racing', 'Realistic off-road racing in Australian landscapes.', 'Win the championship using high-performance HSV vehicles.', 'An Australian-exclusive expansion of Beetle Adventure Racing.', 'HSV Adventure Racing! features licensed Holden Special Vehicles. Explore massive, secret-filled tracks set in the Australian wilderness on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('human-grand-prix---the-new-generation-japan', 'N64', 'Human Grand Prix - The New Generation (Japan)', '1998', 'Racing', 'Human Entertainment', '2', 'Simulation Racing', 'Professional Formula 1 simulation with 1996 licensing.', 'Win the F1 World Championship as your favorite driver.', 'A Japan-exclusive F1 simulator (Pole Position 64).', 'Human Grand Prix - The New Generation offers a realistic take on F1. Manage car setups and pit strategy in this technically detailed Japanese N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hybrid-heaven-europe-enfrde', 'N64', 'Hybrid Heaven (Europe) (En,Fr,De)', '1999', 'Action RPG', 'KONAMI', '1', 'Hybrid Action RPG', 'Action-adventure with tactical RPG-style combat.', 'Stop a subterranean alien invasion in New York City.', 'The European version of the unique Konami hybrid title.', 'Hybrid Heaven (Europe) blends platforming with a deep "wrestling-style" combat system. Learn new moves and evolve your character in this cinematic sci-fi story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hybrid-heaven-japan', 'N64', 'Hybrid Heaven (Japan)', '1999', 'Action RPG', 'KONAMI', '1', 'Hybrid Action RPG', 'Action-adventure with tactical RPG-style combat.', 'Defeat the "Hybrids" and save the US President.', 'The original Japanese release of the sci-fi adventure.', 'Hybrid Heaven (Japan) features an innovative combat engine where you target specific body parts. Experience the unique 64-bit blend of action and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hybrid-heaven-usa', 'N64', 'Hybrid Heaven (USA)', '1999', 'Action RPG', 'KONAMI', '1', 'Hybrid Action RPG', 'Action-adventure with tactical RPG-style combat.', 'Master the grappling moves and save the world.', 'The North American release of the acclaimed hybrid game.', 'Hybrid Heaven (USA) is an N64 cult classic. With its complex story and deep character customization, it offers a gameplay experience found nowhere else.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hydro-thunder-europe', 'N64', 'Hydro Thunder (Europe)', '1999', 'Racing', 'Midway', '4', 'Arcade Racing', 'Arcade boat racing with high-octane physics.', 'Pilot powerful speedboats through treacherous waters.', 'The European release of the Midway arcade hit.', 'Hydro Thunder (Europe) features massive waves and destructible environments. Race from the Arctic to the Nile in this fast-paced maritime brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hydro-thunder-france', 'N64', 'Hydro Thunder (France)', '1999', 'Racing', 'Midway', '4', 'Arcade Racing', 'Arcade boat racing with localized French text.', 'Reach the finish line first in this French localized edition.', 'The localized French version of the water-racing hit.', 'Hydro Thunder (France) brings the roar of the engines to French fans. Master the "Hydro-Jump" and discover secret paths in this 64-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hydro-thunder-usa', 'N64', 'Hydro Thunder (USA)', '1999', 'Racing', 'Midway', '4', 'Arcade Racing', 'Arcade boat racing with high-octane physics.', 'Unlock the most powerful secret boats in North America.', 'The definitive North American release of Hydro Thunder.', 'Hydro Thunder (USA) is a technical powerhouse. Experience spectacular jumps and high-speed crashes in one of the most exciting racers on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-olympics-in-nagano-64-japan', 'N64', 'Hyper Olympics in Nagano 64 (Japan)', '1998', 'Sports', 'KONAMI', '4', 'Olympic Sports', 'Sports simulation with 1998 Winter Olympic events.', 'Win the gold in skiing, snowboarding, and skating.', 'The Japanese release of the Nagano 64 Olympics title.', 'Hyper Olympics in Nagano 64 features realistic athletics and 4-player multiplayer. Compete for the podium in this official Olympic licensed game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ide-yosuke-no-mahjong-juku-japan', 'N64', 'Ide Yosuke no Mahjong Juku (Japan)', '2000', 'Mahjong', 'SCEI', '1', 'Mahjong', 'Professional Mahjong simulation and school.', 'Learn the rules and master the art of Mahjong.', 'A specialized Japan-exclusive Mahjong educator.', 'Ide Yosuke no Mahjong Juku offers deep tutorials and competitive play. Perfect for fans of the traditional game looking for a 64-bit challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iggy-kun-no-bura-bura-poyon-japan', 'N64', 'Iggy-kun no Bura Bura Poyon (Japan)', '1998', 'Platformer', 'Jaleco', '2', 'Physics Platformer', 'Tower-climbing racing with grappling mechanics.', 'Reach the top of the tower before your rivals.', 'The original Japanese release of Iggy''s Reckin'' Balls.', 'Iggy-kun no Bura Bura Poyon is a unique "vertical racer." Use your tongue to grapple and climb through colorful 3D towers in this creative Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iggys-reckin-balls-europe', 'N64', 'Iggy''s Reckin'' Balls (Europe)', '1998', 'Platformer', 'Jaleco', '2', 'Physics Platformer', 'Tower-climbing racing with grappling mechanics.', 'Knock your opponents off the track to win.', 'The European version of the innovative vertical racer.', 'Iggy''s Reckin'' Balls (Europe) features 8 unique characters and chaotic gameplay. It’s a fast-paced blend of racing and combat that’s perfect for 4-player fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iggys-reckin-balls-usa', 'N64', 'Iggy''s Reckin'' Balls (USA)', '1998', 'Platformer', 'Jaleco', '2', 'Physics Platformer', 'Tower-climbing racing with grappling mechanics.', 'Conquer over 100 courses and unlock all characters.', 'The North American release of the cult classic racer.', 'Iggy''s Reckin'' Balls (USA) is known for its original concept and colorful graphics. Master the grappling physics to become the king of the towers on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('in-fisherman---bass-hunter-64-europe', 'N64', 'In-Fisherman - Bass Hunter 64 (Europe)', '1999', 'Sports', 'Asmik Ace', '1', 'Fishing Simulation', 'Realistic bass fishing simulation with career mode.', 'Catch the biggest fish and win the professional tour.', 'The European version of the deep fishing simulator.', 'In-Fisherman - Bass Hunter 64 (Europe) features diverse lakes and realistic fish AI. Use different lures and techniques to land the trophy bass on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('in-fisherman---bass-hunter-64-usa', 'N64', 'In-Fisherman - Bass Hunter 64 (USA)', '1999', 'Sports', 'Asmik Ace', '1', 'Fishing Simulation', 'Realistic bass fishing simulation with career mode.', 'Compete in tournaments across famous American lakes.', 'The North American release of the Bass Hunter 64 hit.', 'In-Fisherman - Bass Hunter 64 (USA) is the premier fishing experience on the system. With its detailed environments and management depth, it’s a must for sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-infernal-machine-usa', 'N64', 'Indiana Jones and the Infernal Machine (USA)', '2000', 'Action Adventure', 'LucasArts', '1', 'Action Adventure', 'Action-adventure with 3D puzzles and exploration.', 'Find the Infernal Machine and stop the Soviet threat.', 'The rare and high-quality N64 port of the PC adventure.', 'Indiana Jones and the Infernal Machine (USA) is a massive game featuring complex level design. Join Indy in this 64-bit epic that rivals Tomb Raider in scope.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indy-racing-2000-usa', 'N64', 'Indy Racing 2000 (USA)', '2000', 'Racing', 'Paradigm Entertainment', '2', 'Simulation Racing', 'Professional Indy-car racing with realistic physics.', 'Win the Indianapolis 500 and master the season.', 'A high-speed open-wheel racing simulation for N64.', 'Indy Racing 2000 (USA) features licensed tracks and drivers. Experience the intensity of 220mph racing with authentic pit stops and car damage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('infinite-64', 'N64', 'Infinite 64', '2022', 'Adventure', 'Independent', '1', 'Fan Game', '3D platforming with an infinite, procedurally generated feel.', 'Explore a world that never ends in this SM64 mod.', 'A technical mod focusing on massive scale and exploration.', 'Infinite 64 challenges you to navigate through vast, custom-generated environments. Experience the limitless potential of the N64 engine in this unique fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-98-europe', 'N64', 'International Superstar Soccer ''98 (Europe)', '1997', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with 1998 rosters and world cup mode.', 'Lead your national team to the trophy in Europe.', 'The European release of the legendary ISS ''98.', 'International Superstar Soccer ''98 (Europe) is widely considered the best soccer game on the system. Master the "Through Ball" and "One-Two" passes to win.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-98-usa', 'N64', 'International Superstar Soccer ''98 (USA)', '1997', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with 1998 rosters and world cup mode.', 'Conquer the international circuit in North America.', 'The North American release of the acclaimed soccer title.', 'International Superstar Soccer ''98 (USA) features fluid animations and strategic depth. It’s a 64-bit sports masterpiece that defined a generation of football games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-2000-europe-ende', 'N64', 'International Superstar Soccer 2000 (Europe) (En,De)', '1999', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with management and RPG elements.', 'Win the championship in the definitive European edition.', 'The European multi-language release of the final ISS entry.', 'International Superstar Soccer 2000 (Europe) features the "Career Mode" where you train a specific player. It’s the most feature-rich soccer game on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-2000-europe-frit', 'N64', 'International Superstar Soccer 2000 (Europe) (Fr,It)', '1999', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with localized French and Italian text.', 'Rise to glory in this Mediterranean localized edition.', 'The localized French/Italian version of ISS 2000.', 'ISS 2000 (Fr/It) offers the same deep gameplay and career mode for specific European markets. Experience the peak of Konami''s soccer engineering on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-2000-usa-enes', 'N64', 'International Superstar Soccer 2000 (USA) (En,Es)', '1999', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with localized English and Spanish text.', 'Lead the USA or Mexico to glory in this Americas edition.', 'The North American release of the final ISS title.', 'International Superstar Soccer 2000 (USA) includes English and Spanish commentary. With its deep mechanics and realistic AI, it’s the ultimate N64 sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-64-europe', 'N64', 'International Superstar Soccer 64 (Europe)', '1997', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with arcade-style movement.', 'Win the International Cup in the European 3D debut.', 'The first ISS entry on the N64 for the European market.', 'International Superstar Soccer 64 (Europe) set the bar for 3D sports. Experience the iconic "Goal!" announcements and fluid 64-bit gameplay for the first time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-64-usa', 'N64', 'International Superstar Soccer 64 (USA)', '1997', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with arcade-style movement.', 'Become the world champion in this North American hit.', 'The definitive North American release of ISS 64.', 'International Superstar Soccer 64 (USA) is a cult classic. Known for its perfect balance and fun multiplayer, it remains one of the most playable sports games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-track-&-field---summer-games-europe-enfrde', 'N64', 'International Track & Field - Summer Games (Europe) (En,Fr,De)', '1998', 'Sports', 'KONAMI', '4', 'Athletics', 'Athletics simulation with button-mashing mechanics.', 'Win gold in various summer sports like 100m sprint and long jump.', 'The European version of Konami''s premier track and field sim.', 'International Track & Field - Summer Games features competitive multiplayer and 11 different Olympic events. Master the rhythm and power to break world records on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-track-&-field-2000-usa', 'N64', 'International Track & Field 2000 (USA)', '2000', 'Sports', 'KONAMI', '4', 'Athletics', 'Athletics simulation with button-mashing mechanics.', 'Compete in the ultimate multi-sport tournament in the USA.', 'The North American release of Konami''s athletics hit.', 'International Track & Field 2000 brings high-energy Olympic action to the N64. With improved 3D graphics and responsive controls, it''s the perfect 4-player party game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('irish-the-hedgehog-64-stpatrick', 'N64', 'Irish The Hedgehog 64 ST.Patrick', '2021', 'Platformer', 'Independent', '1', 'Fan Game', '3D platforming featuring a festive Irish Sonic.', 'Collect stars and shamrocks in a St. Patrick''s Day themed world.', 'A charming character-swap mod for Super Mario 64.', 'Irish The Hedgehog 64 features a custom-modeled green Sonic with Irish flair. Explore festive custom levels in this unique and colorful N64 fan project.');